:root {
  --ink: #0a0e20;
  --ink-2: #121a36;
  --paper: #f6f2e8;
  --orange: #ff9f1c;
  --orange-hot: #ff6b35;
  --yellow: #ffe66d;
  --blue: #38bdf8;
  --blue-deep: #0b6fb8;
  --purple: #b06bff;
