}

/* ------------------------------------------------------------------ HUD */
.hud {
  position: absolute; z-index: 12;
  top: 0; left: 0; right: 0;
  padding: calc(10px + env(safe-area-inset-top)) max(12px, env(safe-area-inset-left)) 0 max(12px, env(safe-area-inset-right));
