.worm-chip { flex: 1; min-width: 0; }
.worm-chip .chip-name {
  display: flex; justify-content: space-between;
  font: 700 8px/1 var(--body); letter-spacing: .09em; color: rgba(255,255,255,.6);
  margin-bottom: 3px; text-transform: uppercase;
}
.team-b .chip-name { flex-direction: row-reverse; }
.chip-name .ko { color: rgba(255,255,255,.3); }
.worm-chip .bar {
  height: 4px; border-radius: 3px; background: rgba(255,255,255,.1); overflow: hidden;
}
.worm-chip .bar i {
  display: block; height: 100%; width: 100%;
  background: linear-gradient(90deg, var(--team-color), color-mix(in srgb, var(--team-color) 55%, #fff));
  border-radius: 3px; transition: width .3s ease;
}
.worm-chip.dead { opacity: .35; }

.match-card {
  display: flex; flex-direction: column; align-items: center; gap: 3px;
  padding-top: 1px;
}
.round-label {
  font: 900 9px/1 var(--display); letter-spacing: .18em; color: rgba(255,255,255,.55);
  text-shadow: 0 1px 0 #000;
  white-space: nowrap;
}
.timer-ring {
  position: relative; width: 52px; height: 52px;
  display: grid; place-items: center;
  filter: drop-shadow(0 6px 12px rgba(0,0,0,.32));
}
.timer-ring svg { position: absolute; inset: 0; width: 100%; height: 100%; transform: rotate(-90deg); }
.timer-track { fill: rgba(8,12,28,.72); stroke: rgba(255,255,255,.14); stroke-width: 4; }
.timer-fill {
  fill: none; stroke: var(--orange); stroke-width: 4; stroke-linecap: round;
  stroke-dasharray: 144.5; stroke-dashoffset: 0;
  transition: stroke .25s, stroke-dashoffset .3s linear;
}
.timer-ring.warn .timer-fill { stroke: var(--red); }
.timer-ring.warn { animation: pulse-warn .75s infinite; }
@keyframes pulse-warn { 50% { filter: drop-shadow(0 0 10px rgba(255,77,109,.8)); } }
.timer-ring span {
  position: relative; z-index: 1;
  font: 900 17px/1 var(--display); letter-spacing: -.04em; color: #fff;
}
.wind-pill {
  display: flex; align-items: center; gap: 3px;
  height: 18px; padding: 0 7px;
  border-radius: 20px;
  background: rgba(8,12,28,.75);
  border: 1px solid rgba(255,255,255,.11);
  font: 700 9px/1 var(--body); color: rgba(255,255,255,.8);
  white-space: nowrap;
}
.wind-pill .wind-arrow { color: var(--blue); font-size: 12px; line-height: 1; transform-origin: 50% 50%; }
.wind-pill b { color: #fff; font-family: var(--display); font-size: 10px; }
.wind-pill .wind-unit { font-size: 7px; opacity: .5; letter-spacing: .06em; }

/* --------------------------------------------------------------- BANNER */
.banner {
  position: absolute; z-index: 14;
  top: clamp(88px, 14vh, 150px); left: 50%;
  transform: translate(-50%, -12px);
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 12px 42px 13px;
  text-align: center;
  opacity: 0; pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(8,12,28,.82) 18%, rgba(8,12,28,.82) 82%, transparent);
  filter: drop-shadow(0 12px 22px rgba(0,0,0,.4));
  transition: opacity .25s ease, transform .25s ease;
  white-space: nowrap;
}
.banner::before, .banner::after {
  content: ""; position: absolute; top: 0; height: 2px; width: 46%;
  background: linear-gradient(90deg, transparent, var(--banner-color, var(--orange)));
}
.banner::before { left: 0; }
.banner::after { right: 0; transform: scaleX(-1); }
.banner.show { opacity: 1; transform: translate(-50%, 0); }
.banner-kicker { font: 700 9px/1 var(--body); letter-spacing: .3em; color: var(--banner-color, var(--orange)); }
.banner-title {
  font: 900 clamp(20px, 3.3vw, 34px)/1 var(--display); font-style: italic;
  letter-spacing: .015em; text-transform: uppercase;
  text-shadow: 0 3px 0 rgba(0,0,0,.4), 0 0 24px color-mix(in srgb, var(--banner-color, var(--orange)) 45%, transparent);
}
.banner-sub { font: 600 10px/1.3 var(--body); color: rgba(255,255,255,.65); letter-spacing: .04em; }

.toast {
  position: absolute; z-index: 15; left: 50%; bottom: calc(var(--controls-h) + 22px);
  transform: translate(-50%, 12px);
  padding: 8px 18px;
  border-radius: 4px;
  background: rgba(8,12,28,.9);
  border: 1px solid rgba(255,255,255,.16);
  box-shadow: 0 10px 30px rgba(0,0,0,.4);
  font: 800 11px/1 var(--display); letter-spacing: .08em;
  opacity: 0; pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  white-space: nowrap;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.good { border-color: rgba(126,224,129,.5); color: var(--green); }
.toast.bad { border-color: rgba(255,77,109,.5); color: var(--red); }

/* --------------------------------------------------------------- HINTS */
.field-hints {
  position: absolute; z-index: 13; top: calc(var(--header-h) + 18px); right: max(14px, env(safe-area-inset-right));
  display: flex; align-items: center; gap: 8px;
}
.sound-btn, .help-btn {
  width: 30px; height: 30px; border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(8,12,28,.65); border: 1px solid rgba(255,255,255,.16);
  color: rgba(255,255,255,.75); backdrop-filter: blur(8px);
  transition: background .15s, color .15s, transform .15s;
}
.sound-btn:hover, .help-btn:hover { background: rgba(255,255,255,.14); color: #fff; transform: translateY(-1px); }
.sound-btn svg { width: 16px; height: 16px; }
.sound-btn .icon-off { display: none; }
.sound-btn.muted .icon-on { display: none; }
.sound-btn.muted .icon-off { display: block; }
.help-btn { font: 900 15px/1 var(--display); }
.aim-hint {
  display: flex; align-items: center; gap: 7px;
  padding: 7px 11px; border-radius: 20px;
  background: rgba(8,12,28,.62); border: 1px solid rgba(255,255,255,.12);
  backdrop-filter: blur(8px);
  font: 800 8px/1 var(--display); letter-spacing: .12em; color: rgba(255,255,255,.65);
  transition: opacity .4s;
}
.aim-hint.hide { opacity: 0; }
.mouse-dot {
  width: 9px; height: 9px; border-radius: 50%;
  border: 2px solid var(--orange); box-shadow: 0 0 8px rgba(255,159,28,.6);
}

/* ------------------------------------------------------------- CONTROLS */
.controls {
  position: absolute; z-index: 13; left: 0; right: 0; bottom: 0;
  display: grid;
  grid-template-columns: minmax(260px, 1fr) auto minmax(210px, 1fr);
  align-items: center;
  gap: clamp(10px, 2vw, 26px);
  min-height: var(--controls-h);
  padding: 12px max(18px, env(safe-area-inset-right)) calc(12px + env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
  background:
    linear-gradient(180deg, transparent 0%, rgba(6,9,22,.68) 22%, rgba(5,8,20,.92) 100%);
  pointer-events: none;
  transition: opacity .4s ease;
}
.controls::before {
  content: ""; position: absolute; left: 0; right: 0; top: 16px; height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.12) 25%, rgba(255,255,255,.12) 75%, transparent);
}
.controls > * { pointer-events: auto; }

.active-profile {
  display: flex; align-items: center; gap: 10px;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(255,255,255,.1);
  border-radius: 6px;
  background: linear-gradient(120deg, rgba(20,28,58,.82), rgba(10,15,34,.55));
  box-shadow: inset 0 1px rgba(255,255,255,.08);
}
.profile-portrait {
  flex: none; width: 46px; height: 46px;
  display: grid; place-items: center;
  color: var(--orange);
  background: radial-gradient(circle at 40% 30%, rgba(255,159,28,.28), rgba(255,159,28,.04) 70%);
  border: 1px solid rgba(255,159,28,.35);
  border-radius: 4px;
  filter: drop-shadow(0 4px 8px rgba(0,0,0,.35));
}
.profile-portrait svg { width: 36px; height: 36px; }
.profile-copy { flex: 1; min-width: 0; }
.profile-top {
  display: flex; justify-content: space-between; align-items: baseline;
  font: 900 13px/1 var(--display); letter-spacing: .04em;
}
.profile-top span:first-child { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.profile-hp { color: var(--orange); font-size: 15px; }
.profile-hp::after { content: " HP"; font-size: 7px; opacity: .65; letter-spacing: .08em; }
.profile-bars { display: flex; flex-direction: column; gap: 3px; margin-top: 5px; }
.mini-bar { height: 4px; border-radius: 3px; background: rgba(255,255,255,.1); overflow: hidden; }
.mini-bar i { display: block; height: 100%; width: 100%; border-radius: 3px; transition: width .2s; }
.mini-bar.hp i { background: linear-gradient(90deg, var(--orange-hot), var(--orange), var(--yellow)); }
.mini-bar.fuel i { background: linear-gradient(90deg, var(--blue-deep), var(--blue)); }
.profile-label {
  display: flex; justify-content: space-between; margin-top: 3px;
  font: 700 6.5px/1 var(--body); letter-spacing: .1em; color: rgba(255,255,255,.4);
}
.material-pill {
  flex: none; display: grid; grid-template-columns: 15px auto; align-items: center;
  column-gap: 4px;
  padding: 5px 8px;
  border-left: 1px solid rgba(255,255,255,.12);
  color: var(--yellow);
}
.material-pill svg { width: 15px; height: 15px; grid-row: 1 / 3; }
.material-pill b { font: 900 14px/1 var(--display); color: #fff; }
.material-pill span { font: 700 6.5px/1 var(--body); letter-spacing: .12em; color: rgba(255,255,255,.5); }

.hotbar-wrap { display: flex; flex-direction: column; align-items: center; gap: 6px; }
.hotbar { display: flex; gap: 7px; align-items: stretch; }
.hotbar[hidden] { display: none; }
.hotbar-tip {
  font: 700 7.5px/1 var(--body); letter-spacing: .16em; color: rgba(255,255,255,.38);
  white-space: nowrap;
}
.weapon-card {
  position: relative;
  width: 84px; height: 62px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  background: linear-gradient(155deg, rgba(32,42,78,.9), rgba(13,19,42,.86));
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 5px;
  transform: skewX(-3deg);
  transition: transform .13s ease, border-color .13s, background .13s, box-shadow .13s;
  overflow: hidden;
  padding: 4px;
}
.weapon-card::before {
  content: ""; position: absolute; inset: 0 0 auto; height: 2px;
  background: linear-gradient(90deg, transparent, var(--card-accent, var(--orange)), transparent);
  opacity: .55;
}
.weapon-card:hover { transform: skewX(-3deg) translateY(-3px); border-color: rgba(255,255,255,.32); }
.weapon-card.active {
  transform: skewX(-3deg) translateY(-5px);
  border-color: var(--orange);
  background: linear-gradient(155deg, rgba(255,159,28,.28), rgba(31,23,18,.9));
  box-shadow: 0 8px 24px rgba(255,107,53,.25), inset 0 0 18px rgba(255,159,28,.12);
}
.weapon-card .wc-icon { width: 32px; height: 24px; color: var(--card-accent, var(--orange)); }
.weapon-card .wc-icon svg { width: 100%; height: 100%; display: block; }
.weapon-card .wc-name { font: 900 8px/1 var(--display); letter-spacing: .09em; color: #fff; }
.weapon-card .wc-key {
  position: absolute; top: 4px; right: 5px;
  font: 900 8px/1 var(--display); color: rgba(255,255,255,.35);
}
.weapon-card .wc-ammo {
  position: absolute; bottom: 4px; right: 5px;
  font: 700 6.5px/1 var(--body); letter-spacing: .05em; color: rgba(255,255,255,.35);
}
.weapon-card.building { width: 76px; height: 58px; }
.weapon-card .cost {
  font: 800 7px/1 var(--body); color: var(--yellow); letter-spacing: .05em;
}
.weapon-card .cost::before { content: "◆ "; font-size: 6px; opacity: .8; }

.build-bar { align-items: center; }
.mat-chips { display: flex; flex-direction: column; gap: 3px; margin-left: 4px; }
.mat-chip {
  height: 18px; padding: 0 8px; border-radius: 3px;
  border: 1px solid rgba(255,255,255,.14);
  background: rgba(10,15,34,.85);
  display: flex; align-items: center; gap: 5px;
  font: 800 7.5px/1 var(--display); letter-spacing: .06em; color: rgba(255,255,255,.6);
  transition: all .13s;
}
.mat-chip i { width: 7px; height: 7px; border-radius: 1px; background: var(--mat-color); }
.mat-chip.active { border-color: var(--yellow); color: #fff; background: rgba(255,230,109,.12); }
.mat-chip:hover { color: #fff; border-color: rgba(255,255,255,.35); }

.action-stack { display: flex; flex-direction: column; align-items: stretch; gap: 6px; justify-self: end; width: 100%; max-width: 230px; }
.mode-btn {
  height: 38px; padding: 0 12px;
  display: flex; align-items: center; gap: 8px;
  border: 1px solid rgba(56,189,248,.45);
  background: linear-gradient(120deg, rgba(14,96,146,.55), rgba(9,25,48,.85));
  border-radius: 4px;
  font: 900 11px/1 var(--display); letter-spacing: .11em; color: #dff5ff;
  box-shadow: 0 4px 16px rgba(0,0,0,.25), inset 0 1px rgba(255,255,255,.12);
  transition: all .15s;
}
.mode-btn:hover { border-color: var(--blue); background: linear-gradient(120deg, rgba(20,130,185,.7), rgba(10,32,58,.9)); }
.mode-btn.build-active {
  border-color: var(--blue); color: #fff;
  background: linear-gradient(120deg, rgba(20,130,185,.9), rgba(10,52,82,.92));
  box-shadow: 0 0 20px rgba(56,189,248,.25), inset 0 1px rgba(255,255,255,.2);
}
.mode-icon { width: 16px; height: 16px; display: grid; place-items: center; flex: none; }
.mode-icon svg { width: 16px; height: 16px; }
.mode-btn #modeLabel { flex: 1; text-align: left; }
.mode-btn kbd { background: rgba(0,0,0,.25); border-color: rgba(255,255,255,.2); }
.end-btn {
  height: 30px;
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 4px;
  background: rgba(255,255,255,.055);
  font: 900 9px/1 var(--display); letter-spacing: .14em; color: rgba(255,255,255,.7);
  transition: all .15s;
}
.end-btn:hover { background: rgba(255,255,255,.13); color: #fff; border-color: rgba(255,255,255,.3); }
.end-btn:disabled { opacity: .35; cursor: default; }

/* ------------------------------------------------------------- TOUCH MOVE */
.touch-move {
  position: absolute; z-index: 13;
  left: max(14px, env(safe-area-inset-left));
  bottom: calc(var(--controls-h) + 14px);
  display: none; align-items: center; gap: 8px;
  transition: opacity .3s;
}
.move-btn {
  width: 52px; height: 52px; border-radius: 50%;
  display: grid; place-items: center;
  background: rgba(8,12,28,.62);
  border: 1px solid rgba(255,255,255,.2);
  color: rgba(255,255,255,.8);
  backdrop-filter: blur(6px);
  box-shadow: 0 6px 16px rgba(0,0,0,.3), inset 0 1px rgba(255,255,255,.1);
  touch-action: none;
}
.move-btn svg { width: 21px; height: 21px; }
.move-btn:active, .move-btn.held { background: rgba(255,159,28,.35); border-color: var(--orange); color: #fff; }
.move-btn.jump { width: 44px; height: 44px; margin-left: 2px; }

/* ---------------------------------------------------------------- START */
.overlay {
  position: absolute; inset: 0; z-index: 30;
  display: grid; place-items: center;
  padding: max(20px, env(safe-area-inset-top)) max(20px, env(safe-area-inset-right)) max(20px, env(safe-area-inset-bottom)) max(20px, env(safe-area-inset-left));
  transition: opacity .55s ease, visibility .55s;
}
.overlay.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.start-screen {
  align-content: center;
  background:
    radial-gradient(ellipse at 50% 45%, rgba(5,8,20,.14) 0%, rgba(5,8,20,.42) 45%, rgba(5,8,20,.8) 100%),
    linear-gradient(180deg, rgba(6,9,22,.45), rgba(6,9,22,.1) 40%, rgba(6,9,22,.72));
  overflow: hidden;
}
.start-glow {
  position: absolute; width: 80vw; height: 80vw; max-width: 900px; max-height: 900px;
  left: 50%; top: 42%; transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(255,159,28,.13), transparent 62%);
  pointer-events: none;
  animation: breathe 7s ease-in-out infinite;
}
@keyframes breathe { 50% { transform: translate(-50%, -50%) scale(1.12); opacity: .7; } }
.start-inner {
  position: relative; z-index: 2;
  display: flex; flex-direction: column; align-items: center;
  text-align: center;
  width: min(760px, 92vw);
  animation: intro-up .8s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes intro-up { from { opacity: 0; transform: translateY(22px); } }
.start-badge {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 12px;
  font: 800 8.5px/1 var(--display); letter-spacing: .22em; color: var(--orange);
  border: 1px solid rgba(255,159,28,.38);
  border-radius: 2px;
  background: rgba(10,14,32,.5);
  backdrop-filter: blur(6px);
  margin-bottom: clamp(14px, 2.4vh, 26px);
}
.start-badge span { width: 5px; height: 5px; border-radius: 50%; background: var(--orange); box-shadow: 0 0 10px var(--orange); animation: blink 2s infinite; }
@keyframes blink { 50% { opacity: .35; } }
.logo {
  margin: 0; display: flex; flex-direction: column; align-items: center;
  line-height: .76; letter-spacing: -.035em;
  transform: skewX(-4deg) rotate(-1deg);
  filter: drop-shadow(0 14px 22px rgba(0,0,0,.5));
}
.logo-line { display: flex; align-items: flex-start; }
.logo-build, .logo-blast {
  font: 900 clamp(58px, 12.5vw, 142px)/.82 var(--display);
  font-style: italic;
  -webkit-text-stroke: clamp(2px, .35vw, 5px) rgba(7,10,24,.95);
  paint-order: stroke fill;
  letter-spacing: -.04em;
}
.logo-build {
  color: #f7fbff;
  background: linear-gradient(180deg, #fff 12%, #d7f0ff 52%, #8ed8ff 100%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: none;
}
.logo-amp {
  font: 900 clamp(26px, 4.2vw, 48px)/1 var(--display);
  color: var(--yellow);
  margin: 0 .12em;
  transform: translateY(.15em) rotate(5deg);
  -webkit-text-stroke: clamp(1px, .2vw, 3px) rgba(7,10,24,.95);
  paint-order: stroke fill;
}
.logo-line.two { margin-top: .04em; }
.logo-blast {
  color: var(--yellow);
  background: linear-gradient(180deg, #fff7c2 5%, var(--yellow) 38%, var(--orange) 76%, #ff6b35 100%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent;
  transform: scaleX(1.1);
  filter: drop-shadow(0 .07em 0 #6b2d10);
}
.start-tag {
  margin: clamp(18px, 3vh, 30px) 0 0;
  font: 600 clamp(13px, 1.5vw, 17px)/1.5 var(--body);
  color: rgba(255,255,255,.72);
  letter-spacing: .015em;
}
.start-tag b { color: #fff; }
.start-features {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 18px;
  margin-top: 14px;
  font: 800 8px/1 var(--display); letter-spacing: .14em; color: rgba(255,255,255,.46);
}
.start-features span { display: flex; align-items: center; gap: 6px; }
.dot { width: 5px; height: 5px; border-radius: 50%; }
.dot.orange { background: var(--orange); box-shadow: 0 0 8px var(--orange); }
.dot.blue { background: var(--blue); box-shadow: 0 0 8px var(--blue); }
.dot.purple { background: var(--purple); box-shadow: 0 0 8px var(--purple); }
.start-actions { display: flex; align-items: stretch; gap: 10px; margin-top: clamp(20px, 3.6vh, 36px); }
.start-btn {
  position: relative;
  min-width: clamp(190px, 22vw, 250px); height: 56px;
  padding: 0 26px;
  display: flex; align-items: center; justify-content: center; gap: 14px;
  background: linear-gradient(120deg, var(--orange-hot), var(--orange) 45%, var(--yellow));
  color: #171006;
  border-radius: 3px;
  font: 900 15px/1 var(--display); letter-spacing: .12em;
  transform: skewX(-5deg);
  box-shadow: 0 10px 30px rgba(255,107,53,.32), 0 2px 0 #a84b12, inset 0 2px rgba(255,255,255,.4);
  transition: transform .15s ease, box-shadow .15s, filter .15s;
}
.start-btn span { transform: skewX(5deg); }
.start-btn i { font-style: normal; font-size: 15px; transform: skewX(5deg); }
.start-btn:hover { transform: skewX(-5deg) translateY(-3px); filter: brightness(1.08); box-shadow: 0 15px 40px rgba(255,107,53,.45), 0 2px 0 #a84b12, inset 0 2px rgba(255,255,255,.45); }
.start-btn:active { transform: skewX(-5deg) translateY(1px); }
.how-btn {
  padding: 0 22px;
  border: 1px solid rgba(255,255,255,.26);
  border-radius: 3px;
  background: rgba(10,14,32,.58);
  backdrop-filter: blur(8px);
  font: 900 10px/1 var(--display); letter-spacing: .13em; color: rgba(255,255,255,.82);
  transition: all .15s;
}
.how-btn:hover { background: rgba(255,255,255,.12); border-color: rgba(255,255,255,.45); color: #fff; }
.start-foot {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 16px;
  margin-top: 18px;
  font: 700 7.5px/1 var(--body); letter-spacing: .1em; color: rgba(255,255,255,.4);
}
.start-foot span { display: flex; align-items: center; gap: 4px; }
.start-ticker {
  position: absolute; left: 0; right: 0; bottom: calc(10px + env(safe-area-inset-bottom));
  display: flex; gap: 18px; justify-content: center;
  font: 700 8px/1 var(--display); letter-spacing: .18em; color: rgba(255,255,255,.22);
  white-space: nowrap; overflow: hidden;
}
.start-ticker span:nth-child(even) { color: var(--orange); opacity: .5; }

/* ----------------------------------------------------------------- HELP */
.help-screen {
  z-index: 40;
  background: rgba(4,7,17,.82);
  backdrop-filter: blur(12px);
}
.help-panel {
  position: relative;
  width: min(920px, 94vw);
  max-height: min(86vh, 720px);
  overflow: auto;
