export const WORLD = { w: 1800, h: 1100 };
export const GRID = 48;
export const RES = 2;
export const WATER_START = 982;
export const GRAVITY = 560;
export const TEAM_COLORS = ['#ff9f1c', '#b06bff'];
export const TEAM_NAMES = ['SUNSET SQUAD', 'STORM SYNDICATE'];
export const WORM_NAMES = [['BISCUIT', 'PEBBLE'], ['VIPER', 'MOSS']];
export const DEFAULT_SEED = 20261031;

export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a);
export const easeOut = t => 1 - Math.pow(1 - t, 3);
export const easeInOut = t => t < .5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
export const rand = (a = 1, b = 0) => b + Math.random() * (a - b);
export const randInt = (a, b) => Math.floor(a + Math.random() * (b - a + 1));
export const pick = arr => arr[Math.floor(Math.random() * arr.length)];

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hash2(x, y, s = 0) {
  let h = x * 374761393 + y * 668265263 + s * 1442695040;
  h = (h ^ (h >> 13)) * 1274126177;
  return ((h ^ (h >> 16)) >>> 0) / 4294967296;
}

export function dist2(x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  return dx * dx + dy * dy;
}

export function pointSegDist2(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  const len = dx * dx + dy * dy;
  let t = len ? ((px - x1) * dx + (py - y1) * dy) / len : 0;
  t = clamp(t, 0, 1);
  const x = x1 + dx * t, y = y1 + dy * t;
  return dist2(px, py, x, y);
}

export function angleLerp(a, b, t) {
  let d = ((b - a + Math.PI * 3) % TAU) - Math.PI;
  return a + d * t;
}

export function fmtTime(s) {
  return Math.max(0, Math.ceil(s));
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

export function polygon(ctx, points) {
  ctx.beginPath();
  points.forEach(([x, y], i) => i ? ctx.lineTo(x, y) : ctx.moveTo(x, y));
  ctx.closePath();
}

export function shade(hex, amt) {
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) + amt, g = ((n >> 8) & 255) + amt, b = (n & 255) + amt;
  r = clamp(r, 0, 255); g = clamp(g, 0, 255); b = clamp(b, 0, 255);
  return '#' + ((r << 16) | (g << 8) | b).toString(16).padStart(6, '0');
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.noise = null;
    this.ambient = null;
  }

  unlock() {
    if (!this.ctx) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.5;
      this.master.connect(this.ctx.destination);
      const len = Math.floor(this.ctx.sampleRate * 1.5);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this.noise = buf;
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) this.master.gain.setTargetAtTime(muted ? 0 : 0.5, this.ctx.currentTime, 0.03);
  }

  tone(freq, dur, opts = {}) {
    if (!this.ctx || this.muted) return;
    const { type = 'sine', gain = 0.14, slide = 0, delay = 0, attack = 0.005 } = opts;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  burst(dur, opts = {}) {
    if (!this.ctx || this.muted || !this.noise) return;
    const { gain = 0.2, freq = 900, q = 0.8, type = 'lowpass', slide = 0, delay = 0 } = opts;
    const t = this.ctx.currentTime + delay;
    const s = this.ctx.createBufferSource();
    s.buffer = this.noise;
    s.playbackRate.value = 0.8 + Math.random() * 0.4;
    const f = this.ctx.createBiquadFilter();
    f.type = type; f.frequency.setValueAtTime(freq, t); f.Q.value = q;
    if (slide) f.frequency.exponentialRampToValueAtTime(Math.max(40, freq * slide), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master);
    s.start(t); s.stop(t + dur + 0.03);
  }

  play(name, opts = {}) {
    if (!this.ctx || this.muted) return;
    switch (name) {
      case 'click':
        this.tone(660, 0.06, { type: 'square', gain: 0.05, slide: 220 });
        break;
      case 'tick':
        this.tone(980, 0.03, { type: 'triangle', gain: 0.03 });
        break;
      case 'build':
        this.burst(0.12, { gain: 0.16, freq: 500, type: 'bandpass', q: 1.4, slide: 0.5 });
        this.tone(150 + Math.random() * 60, 0.1, { type: 'triangle', gain: 0.09, slide: -40 });
        break;
      case 'buildBreak':
        this.burst(0.28, { gain: 0.22, freq: 1400, type: 'bandpass', q: 0.7, slide: 0.2 });
        this.tone(90, 0.2, { type: 'square', gain: 0.06, slide: -35 });
        break;
      case 'shoot':
        this.burst(0.22, { gain: 0.18, freq: 1800, type: 'bandpass', q: 0.8, slide: 0.15 });
        this.tone(140, 0.18, { type: 'sawtooth', gain: 0.1, slide: -90 });
        break;
      case 'shotgun':
        this.burst(0.3, { gain: 0.28, freq: 2200, type: 'lowpass', slide: 0.12 });
        this.tone(75, 0.24, { type: 'square', gain: 0.14, slide: -35 });
        break;
      case 'throw':
        this.burst(0.2, { gain: 0.08, freq: 900, type: 'bandpass', q: 1.2, slide: 1.8 });
        break;
      case 'explode':
        this.burst(0.9, { gain: 0.42, freq: 900, type: 'lowpass', slide: 0.08 });
        this.tone(64, 0.7, { type: 'sine', gain: 0.34, slide: -36 });
        this.tone(110, 0.3, { type: 'triangle', gain: 0.14, slide: -60 });
        break;
      case 'hurt':
        this.tone(190, 0.22, { type: 'sawtooth', gain: 0.12, slide: -90 });
        this.burst(0.12, { gain: 0.1, freq: 700, type: 'bandpass' });
        break;
      case 'jump':
        this.tone(280, 0.13, { type: 'sine', gain: 0.07, slide: 260 });
        break;
      case 'land':
        this.burst(0.08, { gain: 0.07, freq: 300, type: 'lowpass' });
        break;
      case 'splash':
        this.burst(0.5, { gain: 0.22, freq: 1200, type: 'lowpass', slide: 0.25 });
        this.tone(180, 0.3, { type: 'sine', gain: 0.08, slide: -110 });
        break;
      case 'pickup':
        this.tone(660, 0.1, { type: 'triangle', gain: 0.09 });
        this.tone(880, 0.1, { type: 'triangle', gain: 0.08, delay: 0.07 });
        this.tone(1320, 0.16, { type: 'triangle', gain: 0.07, delay: 0.14 });
        break;
      case 'denied':
        this.tone(170, 0.08, { type: 'square', gain: 0.05 });
        this.tone(130, 0.1, { type: 'square', gain: 0.04, delay: 0.08 });
        break;
      case 'turn':
        this.tone(392, 0.12, { type: 'triangle', gain: 0.06 });
        this.tone(523, 0.16, { type: 'triangle', gain: 0.05, delay: 0.1 });
        break;
      case 'victory':
        [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.5, { type: 'triangle', gain: 0.09, delay: i * 0.13 }));
        break;
      case 'defeat':
        [330, 294, 247, 196].forEach((f, i) => this.tone(f, 0.55, { type: 'sawtooth', gain: 0.05, delay: i * 0.16 }));
        break;
      case 'storm':
        this.tone(110, 1.2, { type: 'sawtooth', gain: 0.04, slide: 40 });
        this.burst(1.2, { gain: 0.08, freq: 400, type: 'lowpass', slide: 1.6 });
        break;
      case 'ui':
        this.tone(440 + Math.random() * 80, 0.045, { type: 'square', gain: 0.03 });
        break;
      default:
        break;
    }
  }
}

import { WORLD, RES, WATER_START, clamp, hash2, mulberry32 } from './core.js';

export class Terrain {
  constructor(seed) {
    this.seed = seed;
    this.w = WORLD.w;
    this.h = WORLD.h;
    this.res = RES;
    this.mw = Math.ceil(this.w / this.res);
    this.mh = Math.ceil(this.h / this.res);
    this.mask = new Uint8Array(this.mw * this.mh);
    this.canvas = document.createElement('canvas');
    this.canvas.width = this.w;
    this.canvas.height = this.h;
    this.ctx = this.canvas.getContext('2d');
    this.version = 0;
    this.rng = mulberry32(seed);
    this.generate();
    this.paint();
  }

  generate() {
    const { mw, mh, res, mask } = this;
    const rng = this.rng;

    for (let ix = 0; ix < mw; ix++) {
      const x = ix * res;
      let y = 812
        + Math.sin(x * 0.0048 + 1.1) * 23
        + Math.sin(x * 0.0125 + 0.2) * 8
        + Math.sin(x * 0.027 + 2.3) * 3.2
        + (rng() - 0.5) * 2.4;
      y -= 112 * Math.exp(-Math.pow((x - 900) / 162, 2));
      y -= 18 * Math.exp(-Math.pow((x - 555) / 108, 2));
      y -= 15 * Math.exp(-Math.pow((x - 1245) / 118, 2));
      y += 46 * Math.exp(-Math.pow((x - 742) / 66, 2));
      y += 40 * Math.exp(-Math.pow((x - 1068) / 74, 2));
      y -= 10 * Math.exp(-Math.pow((x - 180) / 80, 2));

      const start = clamp(Math.ceil(y / res), 0, mh);
      for (let iy = start; iy < mh; iy++) mask[iy * mw + ix] = 1;
    }

    // Rugged rock shoulders.
    this.addEllipse(230, 820, 86, 36);
    this.addEllipse(1540, 830, 110, 42);
    this.addEllipse(790, 855, 52, 30);
    this.addEllipse(1090, 870, 62, 28);

    // Floating build islands.
    this.addEllipse(900, 492, 170, 46);
    this.addEllipse(310, 626, 96, 30);
    this.addEllipse(1495, 604, 86, 28);

    // Destroyed edges on the floating island.
    this.carveMaskOnly(838, 510, 28);
    this.carveMaskOnly(963, 500, 20);
  }

  addEllipse(cx, cy, rx, ry) {
    const { mask, mw, mh, res } = this;
    for (let iy = 0; iy < mh; iy++) {
      const y = iy * res;
      const dy = (y - cy) / ry;
      if (Math.abs(dy) > 1) continue;
      const span = rx * Math.sqrt(1 - dy * dy);
      for (let ix = 0; ix < mw; ix++) {
        const x = ix * res;
        if (Math.abs(x - cx) <= span) mask[iy * mw + ix] = 1;
      }
    }
  }

  carveMaskOnly(cx, cy, r) {
    const { mask, mw, mh, res } = this;
    const r2 = r * r;
    const x0 = Math.max(0, Math.floor((cx - r) / res));
    const x1 = Math.min(mw - 1, Math.ceil((cx + r) / res));
    const y0 = Math.max(0, Math.floor((cy - r) / res));
    const y1 = Math.min(mh - 1, Math.ceil((cy + r) / res));
    for (let iy = y0; iy <= y1; iy++) {
      for (let ix = x0; ix <= x1; ix++) {
        const dx = ix * res + res / 2 - cx;
        const dy = iy * res + res / 2 - cy;
        if (dx * dx + dy * dy <= r2) mask[iy * mw + ix] = 0;
      }
    }
  }

  paint() {
    const { mw, mh, res, mask } = this;
    const small = document.createElement('canvas');
    small.width = mw; small.height = mh;
    const sctx = small.getContext('2d');
    const img = sctx.createImageData(mw, mh);
    const data = img.data;

    for (let iy = 0; iy < mh; iy++) {
      const y = iy * res;
      for (let ix = 0; ix < mw; ix++) {
        if (!mask[iy * mw + ix]) continue;
        const n = hash2(ix, iy, this.seed & 255);
        let r, g, b;

        let above = 0;
        while (above < 6 && iy - above - 1 >= 0 && mask[(iy - above - 1) * mw + ix]) above++;
        const openAbove = iy - above - 1 < 0 || !mask[(iy - above - 1) * mw + ix];

        if (openAbove && above <= 4) {
          const grass = ['#a8ee63', '#82d94f', '#5dbb40', '#3f9236', '#2d7232'][above];
          const c = parseInt(grass.slice(1), 16);
          const jitter = (n - 0.5) * 16;
          r = (c >> 16) + jitter; g = ((c >> 8) & 255) + jitter; b = (c & 255) + jitter;
        } else {
          const depth = clamp((y - 560) / 520, 0, 1);
          const baseR = 108 - depth * 34;
          const baseG = 69 - depth * 26;
          const baseB = 45 - depth * 17;
          const grain = (hash2(ix >> 1, iy, 77) - 0.5) * 21 + (n - 0.5) * 9;
          r = baseR + grain; g = baseG + grain * 0.72; b = baseB + grain * 0.52;
          if (n > 0.965 && above > 7) { r += 28; g += 20; b += 12; }
          if (hash2(ix >> 3, iy >> 2, 12) > 0.94 && above > 5) { r -= 18; g -= 14; b -= 9; }
          if (iy + 1 < mh && !mask[(iy + 1) * mw + ix]) { r -= 22; g -= 18; b -= 12; }
        }

        const p = (iy * mw + ix) * 4;
        data[p] = clamp(r, 0, 255);
        data[p + 1] = clamp(g, 0, 255);
        data[p + 2] = clamp(b, 0, 255);
        data[p + 3] = 255;
      }
    }
    sctx.putImageData(img, 0, 0);

    const c = this.ctx;
    c.clearRect(0, 0, this.w, this.h);
    c.imageSmoothingEnabled = true;
    c.imageSmoothingQuality = 'high';
    c.drawImage(small, 0, 0, this.w, this.h);

    // Grass blades and tiny flowers on every exposed top edge.
    const rng = mulberry32(this.seed + 91);
    for (let ix = 2; ix < mw - 2; ix += 2) {
      for (let iy = 2; iy < mh - 1; iy++) {
        if (!mask[iy * mw + ix] || mask[(iy - 1) * mw + ix]) continue;
        const x = ix * res + (rng() - 0.5) * 2;
        const y = iy * res;
        if (y > WATER_START + 10) continue;
        const blades = 1 + Math.floor(rng() * 3);
        c.lineCap = 'round';
        for (let b = 0; b < blades; b++) {
          const h = 3 + rng() * 7;
          const lean = (rng() - 0.5) * 7;
          c.strokeStyle = rng() > 0.35 ? `rgba(${90 + rng() * 55 | 0},${150 + rng() * 70 | 0},${55 + rng() * 30 | 0},.95)` : 'rgba(58,112,48,.9)';
          c.lineWidth = 1 + rng() * 0.8;
          c.beginPath();
          c.moveTo(x + (rng() - 0.5) * 3, y + 1);
          c.quadraticCurveTo(x + lean * 0.4, y - h * 0.6, x + lean, y - h);
          c.stroke();
        }
        if (rng() > 0.965) {
          const colors = ['#ffd166', '#ff8fab', '#fff3b0', '#9be7ff'];
          c.fillStyle = colors[Math.floor(rng() * colors.length)];
          c.beginPath(); c.arc(x + 4, y - 5, 1.6, 0, Math.PI * 2); c.fill();
        }
        break;
      }
    }
    this.version++;
  }

  solidAt(x, y) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return false;
    const ix = (x / this.res) | 0;
    const iy = (y / this.res) | 0;
    return this.mask[iy * this.mw + ix] === 1;
  }

  surfaceBelow(x, maxY) {
    const ix = clamp((x / this.res) | 0, 0, this.mw - 1);
    let iy = clamp((maxY / this.res) | 0, 0, this.mh - 1);
    for (; iy >= 0; iy--) {
      if (this.mask[iy * this.mw + ix]) {
        let top = iy;
        while (top > 0 && this.mask[(top - 1) * this.mw + ix]) top--;
        return top * this.res;
      }
    }
    return null;
  }

  surfaceBetween(x, fromY, toY) {
    if (toY <= fromY) return null;
    const ix = clamp((x / this.res) | 0, 0, this.mw - 1);
    const start = clamp(Math.floor(fromY / this.res), 0, this.mh - 1);
    const end = clamp(Math.ceil(toY / this.res), 0, this.mh - 1);
    for (let iy = start; iy <= end; iy++) {
      if (this.mask[iy * this.mw + ix]) {
        let top = iy;
        while (top > 0 && this.mask[(top - 1) * this.mw + ix]) top--;
        return top * this.res;
      }
    }
    return null;
  }

  carve(cx, cy, r) {
    if (r <= 0) return;
    this.carveMaskOnly(cx, cy, r);
    const c = this.ctx;
    c.save();
    c.globalCompositeOperation = 'source-atop';
    const ring = c.createRadialGradient(cx, cy, Math.max(1, r - 2), cx, cy, r + 12);
    ring.addColorStop(0, 'rgba(28,14,8,0)');
    ring.addColorStop(0.56, 'rgba(38,18,10,.7)');
    ring.addColorStop(0.82, 'rgba(18,9,6,.9)');
    ring.addColorStop(1, 'rgba(18,9,6,0)');
    c.fillStyle = ring;
    c.beginPath(); c.arc(cx, cy, r + 13, 0, Math.PI * 2); c.fill();
    c.globalCompositeOperation = 'destination-out';
    const hole = c.createRadialGradient(cx, cy, Math.max(0, r * 0.82), cx, cy, r);
    hole.addColorStop(0, 'rgba(0,0,0,1)');
    hole.addColorStop(0.85, 'rgba(0,0,0,1)');
    hole.addColorStop(1, 'rgba(0,0,0,.35)');
    c.fillStyle = hole;
    c.beginPath(); c.arc(cx, cy, r, 0, Math.PI * 2); c.fill();
    c.restore();
    this.version++;
  }

  draw(ctx) {
    ctx.drawImage(this.canvas, 0, 0);
  }
}

import { GRID, clamp, hash2, easeOut, lerp } from './core.js';

export const MATERIALS = {
  wood: {
    key: 'wood', label: 'WOOD', hp: 82, cost: 8,
    base: '#a9682f', light: '#c98a4b', dark: '#6f3f1b', line: '#5b3013',
    accent: '#e6a35d', dust: '#b97b3f'
  },
  brick: {
    key: 'brick', label: 'BRICK', hp: 155, cost: 13,
    base: '#b34b3c', light: '#d16b59', dark: '#7c2c24', line: '#5c1f1a',
    accent: '#ee8d7c', dust: '#c06050'
  },
  metal: {
    key: 'metal', label: 'METAL', hp: 255, cost: 20,
    base: '#577089', light: '#7d97b0', dark: '#34475b', line: '#22313f',
    accent: '#a9c3d9', dust: '#91a6ba'
  }
};

const PIECE_COST = { wall: 1, floor: 0.8, ramp: 1.12 };
const PIECE_HP = { wall: 1, floor: 0.62, ramp: 0.88 };

export class Piece {
  constructor({ type, gx, gy, material, team, dir = 1, t = 0 }) {
    this.type = type;
    this.gx = gx;
    this.gy = gy;
    this.material = material;
    this.team = team;
    this.dir = dir;
    this.x = gx * GRID;
    this.y = gy * GRID;
    this.maxHp = Math.round(MATERIALS[material].hp * PIECE_HP[type]);
    this.hp = this.maxHp;
    this.cost = Math.max(3, Math.round(MATERIALS[material].cost * PIECE_COST[type]));
    this.solids = this.computeSolids();
    this.builtAt = t;
    this.flash = 0;
    this.dead = false;
    this.seed = (gx * 73856093) ^ (gy * 19349663) ^ (team * 83492791);
    this.sinceHit = 99;
  }

  computeSolids() {
    const { x, y } = this;
    if (this.type === 'wall') {
      return [{ x: x + 1, y, w: GRID - 2, h: GRID }];
    }
    if (this.type === 'floor') {
      return [{ x: x + 1, y: y + GRID - 13, w: GRID - 2, h: 13 }];
    }
    const out = [];
    for (let i = 0; i < 6; i++) {
      const top = y + GRID - (i + 1) * 8;
      const sx = this.dir > 0 ? x + i * 8 : x + GRID - (i + 1) * 8;
      out.push({ x: sx, y: top, w: 8, h: (i + 1) * 8 });
    }
    return out;
  }

  center() {
    if (this.type === 'floor') return { x: this.x + GRID / 2, y: this.y + GRID - 6 };
    return { x: this.x + GRID / 2, y: this.y + GRID / 2 };
  }

  contains(x, y) {
    for (const s of this.solids) {
      if (x >= s.x && x <= s.x + s.w && y >= s.y && y <= s.y + s.h) return true;
    }
    return false;
  }

  topAt(x, maxY) {
    let best = null;
    for (const s of this.solids) {
      if (x < s.x - 1 || x > s.x + s.w + 1) continue;
      if (s.y <= maxY && (best === null || s.y > best)) best = s.y;
    }
    return best;
  }

  damage(amount, game) {
    if (this.dead) return;
    this.hp -= amount;
    this.flash = 0.18;
    this.sinceHit = 0;
    if (this.hp <= 0) {
      this.dead = true;
      game.onPieceDestroyed(this);
    }
  }

  draw(ctx, time) {
    if (this.dead) return;
    const mat = MATERIALS[this.material];
    const age = time - this.builtAt;
    let scale = 1, alpha = 1;
    if (age < 0.24) {
      const p = clamp(age / 0.24, 0, 1);
      scale = lerp(0.55, 1.04, easeOut(p));
      alpha = clamp(p * 1.8, 0, 1);
    } else if (age < 0.34) {
      scale = lerp(1.04, 1, (age - 0.24) / 0.1);
    }
    const cx = this.x + GRID / 2, cy = this.y + GRID / 2;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(cx, cy);
    ctx.scale(scale, scale);
    ctx.translate(-cx, -cy);
    if (this.flash > 0) ctx.globalAlpha *= 1 + 0;
    this.drawShape(ctx, mat);
    ctx.restore();
  }

  drawShape(ctx, mat) {
    const { x, y } = this;
    const flash = this.flash > 0 ? this.flash / 0.18 : 0;
    const hpFrac = this.hp / this.maxHp;

    if (this.type === 'wall') {
      ctx.fillStyle = flash > 0.4 ? '#ffffff' : mat.dark;
      ctx.fillRect(x + 1, y, GRID - 2, GRID);
      ctx.fillStyle = flash > 0.4 ? '#ffffff' : mat.base;
      ctx.fillRect(x + 5, y + 4, GRID - 10, GRID - 8);
      ctx.strokeStyle = mat.line;
      ctx.lineWidth = 2;
      ctx.strokeRect(x + 5, y + 4, GRID - 10, GRID - 8);
      // frame planks
      ctx.strokeStyle = mat.line;
      ctx.globalAlpha *= 0.55;
      ctx.beginPath();
      ctx.moveTo(x + 5, y + 4); ctx.lineTo(x + GRID - 5, y + GRID - 4);
      ctx.moveTo(x + GRID - 5, y + 4); ctx.lineTo(x + 5, y + GRID - 4);
      ctx.stroke();
      ctx.globalAlpha /= 0.55;
      ctx.fillStyle = mat.light;
      ctx.fillRect(x + 4, y + 4, GRID - 8, 3);
      ctx.fillRect(x + 4, y + 4, 3, GRID - 8);
      // material texture
      if (this.material === 'brick') {
        ctx.strokeStyle = mat.line;
        ctx.lineWidth = 1;
        ctx.globalAlpha *= 0.6;
        for (let row = 0; row < 4; row++) {
          const yy = y + 9 + row * 9;
          ctx.beginPath(); ctx.moveTo(x + 6, yy); ctx.lineTo(x + GRID - 6, yy); ctx.stroke();
          for (let col = 0; col < 2; col++) {
            const xx = x + 6 + ((row % 2) * 16) + col * 32;
            ctx.beginPath(); ctx.moveTo(xx, yy); ctx.lineTo(xx, yy + 9); ctx.stroke();
          }
        }
        ctx.globalAlpha /= 0.6;
      } else if (this.material === 'metal') {
        ctx.fillStyle = mat.light;
        for (const [dx, dy] of [[9, 9], [GRID - 9, 9], [9, GRID - 9], [GRID - 9, GRID - 9]]) {
          ctx.beginPath(); ctx.arc(x + dx, y + dy, 1.8, 0, Math.PI * 2); ctx.fill();
        }
        ctx.strokeStyle = mat.accent;
        ctx.globalAlpha *= 0.35;
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.moveTo(x + 8, y + GRID - 8); ctx.lineTo(x + GRID - 8, y + 8); ctx.stroke();
        ctx.globalAlpha /= 0.35;
      } else {
        ctx.strokeStyle = mat.line;
        ctx.globalAlpha *= 0.5;
        ctx.lineWidth = 1;
        for (let i = 1; i < 4; i++) {
          ctx.beginPath(); ctx.moveTo(x + 6, y + i * 10 + 4); ctx.lineTo(x + GRID - 6, y + i * 10 + 4); ctx.stroke();
        }
        ctx.globalAlpha /= 0.5;
      }
      // team marker
      ctx.fillStyle = this.team === 0 ? '#ff9f1c' : '#b06bff';
      ctx.fillRect(x + GRID - 11, y + 4, 6, 2.5);
    } else if (this.type === 'floor') {
      ctx.fillStyle = mat.dark;
      ctx.fillRect(x + 1, y + GRID - 13, GRID - 2, 13);
      ctx.fillStyle = flash > 0.4 ? '#fff' : mat.base;
      ctx.fillRect(x + 3, y + GRID - 12, GRID - 6, 7);
      ctx.fillStyle = mat.light;
      ctx.fillRect(x + 3, y + GRID - 12, GRID - 6, 2);
      ctx.strokeStyle = mat.line;
      ctx.lineWidth = 1;
      ctx.globalAlpha *= 0.6;
      for (let i = 1; i < 3; i++) {
        ctx.beginPath(); ctx.moveTo(x + i * 16, y + GRID - 11); ctx.lineTo(x + i * 16, y + GRID - 5); ctx.stroke();
      }
      ctx.globalAlpha /= 0.6;
      // diagonal supports underneath
      ctx.strokeStyle = mat.dark;
      ctx.lineWidth = 3;
      ctx.globalAlpha *= 0.55;
      ctx.beginPath();
      ctx.moveTo(x + 6, y + GRID); ctx.lineTo(x + GRID / 2, y + GRID - 11);
      ctx.lineTo(x + GRID - 6, y + GRID);
      ctx.stroke();
      ctx.globalAlpha /= 0.55;
      ctx.fillStyle = this.team === 0 ? '#ff9f1c' : '#b06bff';
      ctx.fillRect(x + GRID / 2 - 3, y + GRID - 13, 6, 2);
    } else {
      // ramp
      const up = this.dir > 0;
      ctx.save();
      ctx.beginPath();
      if (up) {
        ctx.moveTo(x, y + GRID); ctx.lineTo(x + GRID, y + GRID); ctx.lineTo(x + GRID, y + 7);
      } else {
        ctx.moveTo(x, y + GRID); ctx.lineTo(x + GRID, y + GRID); ctx.lineTo(x, y + 7);
      }
      ctx.closePath();
      ctx.fillStyle = mat.dark;
      ctx.fill();
      ctx.clip();
      ctx.fillStyle = flash > 0.4 ? '#fff' : mat.base;
      ctx.fillRect(x, y, GRID, GRID);
      ctx.strokeStyle = mat.line;
      ctx.globalAlpha *= 0.7;
      ctx.lineWidth = 2;
      for (let i = 0; i < 7; i++) {
        ctx.beginPath();
        if (up) { ctx.moveTo(x + i * 9 - 6, y + GRID); ctx.lineTo(x + i * 9 + 16, y); }
        else { ctx.moveTo(x + GRID - i * 9 + 6, y + GRID); ctx.lineTo(x + GRID - i * 9 - 16, y); }
        ctx.stroke();
      }
      ctx.globalAlpha /= 0.7;
      // steps highlight
      ctx.strokeStyle = mat.light;
      ctx.globalAlpha *= 0.55;
      ctx.lineWidth = 2;
      for (let i = 0; i < 6; i++) {
        const top = y + GRID - (i + 1) * 8;
        const sx = up ? x + i * 8 : x + GRID - (i + 1) * 8;
        ctx.beginPath(); ctx.moveTo(sx, top); ctx.lineTo(sx + 8, top); ctx.stroke();
      }
      ctx.globalAlpha /= 0.55;
      ctx.restore();
      ctx.strokeStyle = mat.line;
      ctx.lineWidth = 2;
      ctx.beginPath();
      if (up) { ctx.moveTo(x, y + GRID - 1); ctx.lineTo(x + GRID, y + 7); }
      else { ctx.moveTo(x, y + 7); ctx.lineTo(x + GRID, y + GRID - 1); }
      ctx.stroke();
      ctx.fillStyle = this.team === 0 ? '#ff9f1c' : '#b06bff';
      const markerX = up ? x + GRID - 14 : x + 9;
      ctx.fillRect(markerX, y + 4, 6, 2.5);
    }

    // damage cracks
    if (hpFrac < 0.82) {
      const count = hpFrac < 0.4 ? 4 : 2;
      ctx.strokeStyle = 'rgba(14,9,6,.75)';
      ctx.lineWidth = 1.2;
      for (let i = 0; i < count; i++) {
        const sx = x + 8 + hash2(this.seed, i, 1) * (GRID - 16);
        const sy = y + 7 + hash2(this.seed, i, 2) * (GRID - 14);
        ctx.beginPath();
        ctx.moveTo(sx, sy);
        ctx.lineTo(sx + (hash2(this.seed, i, 3) - 0.5) * 15, sy + 5);
        ctx.lineTo(sx + (hash2(this.seed, i, 4) - 0.5) * 20, sy + 12);
        ctx.stroke();
      }
    }
    if (flash > 0.4) {
      ctx.fillStyle = `rgba(255,255,255,${(flash - 0.4) * 0.8})`;
      ctx.fillRect(x - 1, y - 1, GRID + 2, GRID + 2);
    }
  }
}

import { rand, randInt } from './core.js';

export class FX {
  constructor() {
    this.items = [];
    this.shake = 0;
    this.flash = 0;
    this.flashColor = '255,180,80';
  }

  explode(x, y, radius, colors = {}) {
    const { fire = '#ffb347', smoke = '#4a4a55', dirt = '#8a5a33' } = colors;
    for (let i = 0; i < 26; i++) {
      const a = rand(Math.PI * 2), sp = rand(320, 40);
      this.items.push({
        type: 'fire', x, y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - rand(50),
        life: rand(0.75, 0.25), max: 0.75, size: rand(18, 5),
        color: i % 3 === 0 ? '#fff3b0' : fire, drag: 2.6, rise: 26
      });
    }
    for (let i = 0; i < 18; i++) {
      const a = rand(Math.PI * 2), sp = rand(180, 20);
      this.items.push({
        type: 'smoke', x: x + rand(20, -20), y: y + rand(20, -20),
        vx: Math.cos(a) * sp * 0.5, vy: Math.sin(a) * sp * 0.35 - rand(50, 15),
        life: rand(1.8, 0.8), max: 1.8, size: rand(24, 8),
        color: smoke, drag: 1.1, rise: 22
      });
    }
    for (let i = 0; i < 20; i++) {
      const a = rand(Math.PI * 2), sp = rand(340, 80);
      this.items.push({
        type: 'dirt', x, y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - rand(190, 30),
        life: rand(1.3, 0.5), max: 1.3, size: rand(6, 2), color: dirt,
        rot: rand(Math.PI * 2), vr: rand(10, -10), grav: 900, drag: 0.15
      });
    }
    for (let i = 0; i < 14; i++) {
      const a = rand(Math.PI * 2), sp = rand(460, 120);
      this.items.push({
        type: 'spark', x, y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - rand(60),
        life: rand(0.45, 0.15), max: 0.45, size: rand(2.5, 1), color: '#ffe9a8',
        grav: 420, drag: 0.3
      });
    }
    this.items.push({ type: 'ring', x, y, vx: 0, vy: 0, life: 0.42, max: 0.42, size: 10, radius: radius * 1.15, color: '255,210,140' });
    this.items.push({ type: 'flash', x, y, vx: 0, vy: 0, life: 0.18, max: 0.18, size: radius * 1.6, color: '#fff3c4' });
    this.shake = Math.min(22, this.shake + radius * 0.28);
    this.flash = Math.min(0.5, this.flash + radius * 0.004);
    this.flashColor = '255,180,90';
  }

  muzzle(x, y, angle) {
    for (let i = 0; i < 7; i++) {
      const a = angle + rand(0.35, -0.35);
      const sp = rand(260, 60);
      this.items.push({
        type: 'spark', x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: rand(0.24, 0.08), max: 0.24, size: rand(2.5, 1), color: '#ffd166',
        grav: 80, drag: 2.4
      });
    }
    this.items.push({ type: 'flash', x, y, vx: 0, vy: 0, life: 0.08, max: 0.08, size: 26, color: '#ffe9a8' });
  }

  puff(x, y, color = '#b9b6a8', n = 4, up = 40) {
    for (let i = 0; i < n; i++) {
      this.items.push({
        type: 'smoke', x: x + rand(5, -5), y: y + rand(4, -4),
        vx: rand(24, -24), vy: -rand(up, 5), life: rand(0.7, 0.25), max: 0.7,
        size: rand(7, 2), color, drag: 1.4, rise: 18
      });
    }
  }

  splash(x, y, n = 26) {
    for (let i = 0; i < n; i++) {
      const a = rand(-Math.PI * 0.92, -Math.PI * 0.08);
      const sp = rand(430, 90);
      this.items.push({
        type: 'drop', x: x + rand(14, -14), y,
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
        life: rand(1.1, 0.4), max: 1.1, size: rand(4.5, 1.5),
        color: i % 3 === 0 ? '#d8f7ff' : '#6fd0e8', grav: 880, drag: 0.1
      });
    }
    this.items.push({ type: 'ring', x, y, vx: 0, vy: 0, life: 0.6, max: 0.6, size: 8, radius: 60, color: '150,230,255' });
  }

  text(x, y, str, color = '#ffe66d', size = 18) {
    this.items.push({
      type: 'text', x, y, vx: rand(20, -20), vy: -72, life: 1.1, max: 1.1,
      size, color, str, drag: 1.2
    });
  }

  buildPop(x, y, color) {
    for (let i = 0; i < 8; i++) {
      const a = rand(Math.PI * 2), sp = rand(140, 30);
      this.items.push({
        type: 'spark', x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 30,
        life: rand(0.32, 0.1), max: 0.32, size: rand(2, 0.8),
        color, grav: 100, drag: 1.6
      });
    }
    this.items.push({ type: 'ring', x, y, vx: 0, vy: 0, life: 0.26, max: 0.26, size: 6, radius: 34, color: '120,210,255' });
  }

  debris(x, y, color, n = 14, power = 260) {
    for (let i = 0; i < n; i++) {
      const a = rand(Math.PI * 2), sp = rand(power, 50);
      this.items.push({
        type: 'dirt', x: x + rand(12, -12), y: y + rand(12, -12),
        vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - rand(180, 40),
        life: rand(1.2, 0.4), max: 1.2, size: rand(6, 2), color,
        rot: rand(Math.PI * 2), vr: rand(12, -12), grav: 1000, drag: 0.12
      });
    }
  }

  update(dt) {
    this.shake *= Math.pow(0.0015, dt);
    if (this.shake < 0.2) this.shake = 0;
    this.flash *= Math.pow(0.002, dt);
    if (this.flash < 0.01) this.flash = 0;
    const items = this.items;
    for (let i = items.length - 1; i >= 0; i--) {
      const p = items[i];
      p.life -= dt;
      if (p.life <= 0) { items.splice(i, 1); continue; }
      const drag = p.drag ? Math.pow(1 / (1 + p.drag), dt) : 1;
      p.vx *= drag;
      p.vy *= drag;
      if (p.grav) p.vy += p.grav * dt;
      if (p.rise) p.vy -= p.rise * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      if (p.vr) p.rot += p.vr * dt;
    }
    if (items.length > 700) items.splice(0, items.length - 700);
  }

  drawBehind(ctx) {
    for (const p of this.items) {
      if (p.type !== 'smoke') continue;
      const t = p.life / p.max;
      ctx.globalAlpha = t * 0.3;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * (1.6 - t * 0.6), 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  draw(ctx) {
    for (const p of this.items) {
      const t = Math.max(0, p.life / p.max);
      switch (p.type) {
        case 'spark':
          ctx.globalCompositeOperation = 'lighter';
          ctx.strokeStyle = p.color;
          ctx.globalAlpha = Math.min(1, t * 1.8);
          ctx.lineWidth = p.size;
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(p.x - p.vx * 0.018, p.y - p.vy * 0.018);
          ctx.stroke();
          ctx.globalCompositeOperation = 'source-over';
          break;
        case 'fire':
          ctx.globalCompositeOperation = 'lighter';
          ctx.globalAlpha = t * 0.85;
          ctx.fillStyle = p.color;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size * (0.5 + t * 0.7), 0, Math.PI * 2); ctx.fill();
          ctx.globalCompositeOperation = 'source-over';
          break;
        case 'smoke':
          ctx.globalAlpha = t * 0.22;
          ctx.fillStyle = p.color;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size * (1.7 - t * 0.7), 0, Math.PI * 2); ctx.fill();
          break;
        case 'dirt':
          ctx.globalAlpha = Math.min(1, t * 1.6);
          ctx.fillStyle = p.color;
          ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(p.rot || 0);
          ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size);
          ctx.restore();
          break;
        case 'drop':
          ctx.globalAlpha = Math.min(0.85, t * 1.5);
          ctx.fillStyle = p.color;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();
          break;
        case 'ring':
          ctx.globalAlpha = t * 0.75;
          ctx.strokeStyle = `rgba(${p.color},${t})`;
          ctx.lineWidth = 2 + t * 4;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.radius * (1 - t * 0.8), 0, Math.PI * 2); ctx.stroke();
          break;
        case 'flash':
          ctx.globalCompositeOperation = 'lighter';
          ctx.globalAlpha = t * 0.5;
          const g = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.size);
          g.addColorStop(0, p.color);
          g.addColorStop(0.4, 'rgba(255,200,100,.7)');
          g.addColorStop(1, 'rgba(255,140,50,0)');
          ctx.fillStyle = g;
          ctx.beginPath(); ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2); ctx.fill();
          ctx.globalCompositeOperation = 'source-over';
          break;
        case 'text':
          ctx.globalAlpha = Math.min(1, t * 2.2);
          ctx.font = `900 ${p.size}px "Arial Black", Impact, sans-serif`;
          ctx.textAlign = 'center';
          ctx.lineWidth = 4;
          ctx.strokeStyle = 'rgba(8,10,22,.8)';
          ctx.strokeText(p.str, p.x, p.y);
          ctx.fillStyle = p.color;
          ctx.fillText(p.str, p.x, p.y);
          break;
      }
    }
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
  }
}

import { TAU, clamp } from './core.js';

export class Worm {
  constructor({ team, slot, name, x, y }) {
    this.team = team;
    this.slot = slot;
    this.name = name;
    this.x = x;
    this.y = y;
    this.vx = 0;
    this.vy = 0;
    this.hp = 100;
    this.maxHp = 100;
    this.alive = true;
    this.onGround = true;
    this.facing = team === 0 ? 1 : -1;
    this.fuel = 7.5;
    this.maxFuel = 7.5;
    this.jumps = 4;
    this.aimAngle = team === 0 ? -0.7 : -Math.PI + 0.7;
    this.aimPower = 0.75;
    this.hurtFlash = 0;
    this.recoil = 0;
    this.walkTime = 0;
    this.idleOffset = Math.random() * TAU;
    this.deathTimer = 0;
    this.damageTaken = 0;
    this.shots = 0;
    this.kills = 0;
    this.drowned = false;
  }

  get cx() { return this.x; }
  get cy() { return this.y - 30; }
  get top() { return this.y - 58; }

  center() { return { x: this.x, y: this.y - 30 }; }

  head() {
    return { x: this.x + this.facing * 2, y: this.y - 46 };
  }

  muzzle(angle = this.aimAngle) {
    return {
      x: this.x + Math.cos(angle) * 26 + this.facing * 4,
      y: this.y - 31 + Math.sin(angle) * 26
    };
  }

  resetTurn() {
    this.fuel = this.maxFuel;
    this.jumps = 4;
    this.vx = 0;
    this.vy = 0;
  }

  hurt(amount, game) {
    if (!this.alive) return;
    amount = Math.round(amount);
    this.hp = clamp(this.hp - amount, 0, this.maxHp);
    this.damageTaken += amount;
    this.hurtFlash = 0.45;
    if (this.hp <= 0) {
      this.alive = false;
      this.deathTimer = 0;
      game.onWormDeath(this);
    }
  }

  heal(amount) {
    this.hp = clamp(this.hp + amount, 0, this.maxHp);
  }
}

