import { GRID, WORLD, clamp, rand, dist2 } from './core.js';

export class AI {
  constructor(game) {
    this.game = game;
    this.phase = 'idle';
    this.timer = 0;
    this.plan = null;
    this.shotFired = false;
    this.builtThisTurn = 0;
  }

  begin() {
    this.phase = 'think';
    this.timer = 0.9 + rand(0.5);
    this.plan = null;
    this.shotFired = false;
    this.builtThisTurn = 0;
  }

  update(dt) {
    const g = this.game;
    if (g.state !== 'ai' || !g.activeWorm?.alive) return;
    this.timer -= dt;

    if (this.phase === 'think') {
      if (this.timer > 0) return;
      const me = g.activeWorm;
      const target = g.nearestEnemy(me);
      if (!target) return;
      this.doBuild(me, target);
      this.plan = this.findPlan(me, target);
      this.phase = 'aim';
      this.timer = 0.65;
      if (this.plan) {
        g.aimAngle = this.plan.angle;
        g.aimPower = this.plan.power;
        g.weapon = this.plan.weapon;
        g.ui?.syncWeapon();
      }
      return;
    }

    if (this.phase === 'aim') {
      if (this.timer > 0) return;
      if (!this.plan) this.plan = this.findPlan(g.activeWorm, g.nearestEnemy(g.activeWorm));
      if (!this.plan) {
        g.endTurn();
        return;
      }
      g.aiFire(this.plan);
      this.phase = 'done';
    }
  }

  doBuild(me, target) {
    const g = this.game;
    if (g.mats[1] < 14) return;
    const dist = Math.abs(target.x - me.x);
    const dangerous = me.hp < 62 || dist < 520;
    if (Math.random() > (dangerous ? 0.72 : 0.34)) return;

    const facing = target.x >= me.x ? 1 : -1;
    const x = me.x + facing * (GRID * 1.45);
    const gx = Math.floor(x / GRID);
    const gy = Math.floor((me.y - GRID + 3) / GRID);
    const material = g.mats[1] > 52 && Math.random() < 0.3 ? 'brick' : 'wood';

    let placed = 0;
    if (g.tryPlace(gx, gy, { team: 1, material, type: 'wall', dir: facing, silent: true })) placed++;
    if (placed && g.mats[1] > 24 && Math.random() < 0.46) {
      if (g.tryPlace(gx, gy - 1, { team: 1, material, type: 'wall', dir: facing, silent: true })) placed++;
    }
    if (!placed) {
      // Try a floor under the worm to escape rising water.
      const fy = Math.floor(me.y / GRID) - 1;
      g.tryPlace(Math.floor(me.x / GRID), fy, { team: 1, material: 'wood', type: 'floor', silent: true });
    }
    this.builtThisTurn = placed;
    if (placed) g.showToast(material === 'brick' ? 'SYNDICATE THREW UP BRICK' : 'SYNDICATE THREW UP WOOD', '', 900);
  }

  findPlan(me, target) {
    if (!target) return null;
    const g = this.game;
    const tx = target.x, ty = target.y - 30;
    const dist = Math.abs(target.x - me.x);
    const clear = g.lineOfSight(me.muzzle(), target.center());

    // Pump shotgun for close, unobstructed targets.
    if (dist < 470 && clear && Math.random() < 0.32) {
      const head = target.center();
      const muzzle = me.muzzle();
      const angle = Math.atan2(head.y - muzzle.y, head.x - muzzle.x);
      return {
        weapon: 'shotgun',
        angle: angle + rand(0.035, -0.035),
        power: 1,
        expected: 18
      };
    }

    let best = null;
    const targetPos = { x: tx, y: ty };
    for (let deg = -176; deg <= -4; deg += 2.4) {
      const angle = deg * Math.PI / 180;
      for (let power = 0.28; power <= 1.001; power += 0.045) {
        const hit = g.simulateShot(me, angle, power, 'bazooka');
        if (!hit) continue;
        const d = Math.sqrt(dist2(hit.x, hit.y, tx, ty));
        let score = d;
        if (hit.water) score += 55;
        const selfD = Math.sqrt(dist2(hit.x, hit.y, me.x, me.y - 30));
        if (selfD < 110) score += (110 - selfD) * 7;
        // Prefer shots that land on the enemy's side and in front of their cover.
        if (Math.abs(hit.x - tx) > 160) score += 24;
        if (!best || score < best.score) best = { angle, power, score, hit };
      }
    }
    if (!best) return null;

    // Difficulty-flavoured aim error.
    const errA = rand(0.035, -0.035) * (0.6 + Math.random());
    const errP = rand(0.028, -0.028);
    return {
      weapon: 'bazooka',
      angle: clamp(best.angle + errA, -Math.PI + 0.06, -0.04),
      power: clamp(best.power + errP, 0.25, 1),
      expected: Math.sqrt(dist2(best.hit.x, best.hit.y, tx, ty)),
      score: best.score
    };
  }
}

import {
  WORLD, GRID, WATER_START, GRAVITY, TEAM_COLORS, TEAM_NAMES, WORM_NAMES,
  DEFAULT_SEED, clamp, lerp, rand, randInt, TAU, dist2, mulberry32
} from './core.js';
import { Terrain } from './terrain.js';
import { Piece, MATERIALS } from './pieces.js';
import { Worm } from './worm.js';
import { FX } from './fx.js';
import { AI } from './ai.js';

const WEAPONS = {
  bazooka: { name: 'BAZOOKA', radius: 58, damage: 54, speed: [315, 350], gravity: GRAVITY },
  grenade: { name: 'GRENADE', radius: 72, damage: 45, speed: [330, 320], gravity: GRAVITY, fuse: 2.25 },
  shotgun: { name: 'PUMP', radius: 13, damage: 11, speed: [500, 130] }
};
const WEAPON_ORDER = ['bazooka', 'grenade', 'shotgun'];
const BUILD_ORDER = ['wall', 'floor', 'ramp'];
const BUILD_COST = { wall: 1, floor: 0.8, ramp: 1.12 };
const BUILD_HP = { wall: 1, floor: 0.62, ramp: 0.88 };
const STEP = 15;

class Projectile {
  constructor({ type, owner, team, x, y, angle, power, wind }) {
    this.type = type;
    this.owner = owner;
    this.team = team;
    this.x = x;
    this.y = y;
    this.age = 0;
    if (type === 'grenade') {
      const speed = 300 + power * 330;
      this.vx = Math.cos(angle) * speed;
      this.vy = Math.sin(angle) * speed;
      this.fuse = WEAPONS.grenade.fuse;
      this.bounces = 0;
      this.radius = 6;
    } else {
      const speed = 290 + power * 410;
      this.vx = Math.cos(angle) * speed;
      this.vy = Math.sin(angle) * speed;
      this.fuse = Infinity;
      this.radius = 4;
    }
    this.wind = wind;
    this.trailTimer = 0;
    this.spin = rand(TAU);
  }
}

export class Game {
  constructor(canvas, audio) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.audio = audio;
    this.ui = null;
    this.time = 0;
    this.lastTickSecond = 99;
    this.paused = false;

    this.view = {
      w: 0, h: 0, dpr: 1, zoom: 0.8, camX: 900, camY: 550,
      cx: 0, cy: 0, bottomInset: 148, topInset: 70
    };
    this.keys = { left: false, right: false };
    this.aiming = false;
    this.painting = false;
    this.lastPaintCell = '';
    this.pointer = { x: 900, y: 500, active: false };
    this.buildGhost = null;

    this.weapon = 'bazooka';
    this.mode = 'blast';
    this.buildType = 'wall';
    this.material = 'wood';
    this.rampDir = 1;
    this.state = 'demo';
    this.winner = -1;
    this.timeLeft = 60;
    this.matchTime = 0;
    this.effectsTimer = 0;

    this.reset(DEFAULT_SEED, true);
    this.ai = new AI(this);
    this.resize(window.innerWidth, window.innerHeight);
    this.camX = 900;
    this.camY = 550;
  }

  reset(seed = DEFAULT_SEED, demo = false) {
    this.seed = seed;
    this.terrain = new Terrain(seed);
    this.pieces = [];
    this.projectiles = [];
    this.worms = [];
    this.crates = [];
    this.fx = new FX();
    this.mats = [62, 62];
    this.waterLevel = WATER_START;
    this.round = 1;
    this.activeTeam = 0;
    this.activeWorm = null;
    this.lastActiveSlot = [-1, -1];
    this.turnInTeam = [0, 0];
    this.windDisplay = randInt(-18, 18);
    this.windAccel = this.windDisplay * 4.2;
    this.timeLeft = 60;
    this.lastTickSecond = 99;
    this.aiming = false;
    this.painting = false;
    this.state = demo ? 'demo' : 'aim';
    this.winner = -1;
    this.pendingWinner = null;
    this.matchTime = 0;
    this.mode = 'blast';
    this.weapon = 'bazooka';
    this.buildType = 'wall';
    this.material = 'wood';
    this.buildGhost = null;
    this.turnStart = 0;

    const spawns = [
      { x: 548, team: 0, slot: 0 },
      { x: 648, team: 0, slot: 1 },
      { x: 1252, team: 1, slot: 0 },
      { x: 1148, team: 1, slot: 1 }
    ];
    this.worms = spawns.map(({ x, team, slot }) => {
      const y = this.terrain.surfaceBelow(x, WORLD.h) ?? 800;
      const w = new Worm({
        team, slot, x, y: y - 1,
        name: WORM_NAMES[team][slot]
      });
      w.aimAngle = team === 0 ? -0.62 : -Math.PI + 0.62;
      w.aimPower = 0.74;
      return w;
    });
    if (demo) this.activeWorm = this.worms[0];
    this.setupCrates();
  }

  setupCrates() {
    const spots = [
      { x: 900, maxY: 520 },
      { x: 705, maxY: WORLD.h },
      { x: 1092, maxY: WORLD.h },
      { x: 1470, maxY: WORLD.h }
    ];
    this.crates = spots.map((s, i) => {
      const y = this.terrain.surfaceBelow(s.x, s.maxY) ?? 800;
      return { x: s.x, y: y - 1, vy: 0, alive: true, bob: rand(TAU), id: i, takenBy: -1 };
    }).filter((c, i) => i !== 3 || Math.random() > 0.5);
  }

  setUI(ui) { this.ui = ui; }

  resize(w, h) {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    this.canvas.style.width = w + 'px';
    this.canvas.style.height = h + 'px';
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const controls = document.getElementById('controls');
    const bottomInset = controls ? Math.max(70, controls.getBoundingClientRect().height - 6) : 148;
    this.view.w = w;
    this.view.h = h;
    this.view.dpr = dpr;
    this.view.bottomInset = bottomInset;
    this.view.cx = w / 2;
    this.view.cy = Math.max(180, (h - bottomInset) / 2 + 10);

    const portrait = w / h < 0.84;
    let zoom;
    if (portrait) {
      zoom = clamp(Math.min((w - 18) / 700, (h - bottomInset) / 1120), 0.44, 0.66);
    } else {
      zoom = clamp(Math.max(w / 1800, (h - bottomInset) / 1100), 0.47, 1.14);
    }
    this.view.zoom = zoom;
  }

  get teamColorA() { return TEAM_COLORS[0]; }

  startMatch(seed = DEFAULT_SEED) {
    const finalSeed = seed ?? (Math.floor(Math.random() * 1e9) + 1);
    this.reset(finalSeed, false);
    this.round = 1;
    this.lastActiveSlot = [-1, -1];
    this.state = 'aim';
    this.startTurn(0, true);
    this.ui?.setPlaying(true);
    this.ui?.hideStart();
    this.fx.flash = 0.18;
    this.fx.flashColor = '255,200,120';
  }

  startTurn(team, first = false) {
    const members = this.worms.filter(w => w.team === team && w.alive).sort((a, b) => a.slot - b.slot);
    if (!members.length) {
      this.finishMatch(team === 0 ? 1 : 0);
      return;
    }
    const last = this.lastActiveSlot[team];
    let next = members.find(w => w.slot > last);
    if (!next) next = members[0];
    this.lastActiveSlot[team] = next.slot;
    this.activeTeam = team;
    this.activeWorm = next;
    this.turnInTeam[team]++;
    next.resetTurn();
    this.mats[team] = Math.min(128, this.mats[team] + (first ? 0 : 18));
    this.timeLeft = 60;
    this.lastTickSecond = 99;
    this.aiming = false;
    this.painting = false;
    this.mode = 'blast';
    this.buildGhost = null;
    this.projectiles = [];
    this.windDisplay = randInt(-26, 26);
    this.windAccel = this.windDisplay * 4.2;
    this.turnStart = this.time;

    const target = this.nearestEnemy(next);
    if (target) {
      next.facing = target.x >= next.x ? 1 : -1;
      next.aimAngle = target.x >= next.x ? -0.62 : -Math.PI + 0.62;
      next.aimPower = 0.74;
    }
    this.state = team === 0 ? 'aim' : 'ai';
    this.fx.shake = Math.min(this.fx.shake, 2);

    if (team === 0) {
      this.ui?.banner('YOUR TURN', `${next.name} IS UP`, 'Build cover, then blast the Syndicate.', TEAM_COLORS[0], 2300);
      this.audio.play('turn');
    } else {
      this.ui?.banner('SYNDICATE TURN', `${next.name} IS MAKING A MOVE`, 'Watch the sky. Watch the walls.', TEAM_COLORS[1], 2100);
      this.audio.play('turn');
      this.ai.begin();
    }
    this.ui?.syncAll();
    this.ui?.setMode(this.mode);
  }

  nearestEnemy(worm) {
    if (!worm) return null;
    let best = null, bd = Infinity;
    for (const w of this.worms) {
      if (!w.alive || w.team === worm.team) continue;
      const d = dist2(w.x, w.y, worm.x, worm.y);
      if (d < bd) { bd = d; best = w; }
    }
    return best;
  }

  aliveCount(team) {
    return this.worms.filter(w => w.team === team && w.alive).length;
  }

  /* ------------------------------------------------------------- viewport */
  screenToWorld(sx, sy) {
    const v = this.view;
    return {
      x: v.camX + (sx - v.cx) / v.zoom,
      y: v.camY + (sy - v.cy) / v.zoom
    };
  }

  worldToScreen(x, y) {
    const v = this.view;
    return { x: v.cx + (x - v.camX) * v.zoom, y: v.cy + (y - v.camY) * v.zoom };
  }

  inField(sx, sy) {
    const v = this.view;
    return sy > 52 && sy < v.h - Math.max(60, v.bottomInset - 12);
  }

  updateCamera(dt) {
    const v = this.view;
    let fx = 900, fy = 560;
    if (this.state === 'demo') {
      fx = 900 + Math.sin(this.time * 0.08) * 60;
      fy = 552;
    } else if (this.activeWorm) {
      const active = this.activeWorm;
      fx = active.x;
      fy = 552;
      const target = this.nearestEnemy(active);
      if (target && (this.state === 'aim' || this.state === 'ai')) {
        fx = active.x * 0.56 + target.x * 0.44;
      }
      if (this.state === 'firing' && this.projectiles.length) {
        const p = this.projectiles[0];
        fx = p.x;
        fy = clamp(p.y, 380, 760);
      }
      if (this.state === 'settle' && this.lastHitPoint) {
        fx = this.lastHitPoint.x;
        fy = clamp(this.lastHitPoint.y, 380, 760);
      }
    }
    const halfW = v.w / (2 * v.zoom);
    const halfH = v.h / (2 * v.zoom);
    if (halfW * 2 >= WORLD.w) fx = WORLD.w / 2;
    else fx = clamp(fx, halfW, WORLD.w - halfW);
    if (halfH * 2 >= WORLD.h) fy = WORLD.h / 2;
    else fy = clamp(fy, halfH, WORLD.h - halfH);

    const speed = this.state === 'firing' ? 6.5 : 3.4;
    const k = 1 - Math.exp(-dt * speed);
    this.camX = lerp(this.camX, fx, k);
    this.camY = lerp(this.camY, fy, k);
  }

  /* ---------------------------------------------------------------- input */
  pointerDown(sx, sy) {
    if (this.paused || this.state !== 'aim' || this.activeTeam !== 0 || !this.activeWorm?.alive) return;
    if (!this.inField(sx, sy)) return;
    const p = this.screenToWorld(sx, sy);
    this.pointer = { x: p.x, y: p.y, active: true };
    if (this.mode === 'build') {
      this.painting = true;
      this.lastPaintCell = '';
      this.updateBuildGhost(p.x, p.y);
      this.buildAtGhost();
    } else {
      this.aiming = true;
      this.updateAim(p.x, p.y);
      this.ui?.hideAimHint();
    }
  }

  pointerMove(sx, sy, down) {
    if (this.state !== 'aim' || this.activeTeam !== 0 || !this.activeWorm?.alive) return;
    if (!this.inField(sx, sy)) return;
    const p = this.screenToWorld(sx, sy);
    this.pointer = { x: p.x, y: p.y, active: !!down };
    if (this.mode === 'build') {
      this.updateBuildGhost(p.x, p.y);
      if (down && this.painting) this.buildAtGhost();
    } else if (this.aiming && down) {
      this.updateAim(p.x, p.y);
    }
  }

  pointerUp() {
    if (this.aiming && this.state === 'aim' && this.activeWorm?.alive) {
      this.aiming = false;
      this.fireActive();
    }
    this.painting = false;
    this.lastPaintCell = '';
  }

  pointerCancel() {
    this.aiming = false;
    this.painting = false;
  }

  updateAim(wx, wy) {
    const w = this.activeWorm;
    if (!w) return;
    const mx = w.x, my = w.y - 31;
    const dx = wx - mx, dy = wy - my;
    const dist = Math.hypot(dx, dy);
    let angle = Math.atan2(dy, dx);
    // Prevent aiming straight into your own feet.
    if (angle > -0.06 && angle < Math.PI - 0.06) {
      angle = dy > 0 ? Math.min(angle, Math.PI - 0.12) : -0.08;
    }
    w.aimAngle = angle;
    w.facing = Math.cos(angle) >= 0 ? 1 : -1;
    w.aimPower = clamp(dist / 335, 0.18, 1);
  }

  toggleMode(force) {
    if (this.state !== 'aim' || this.activeTeam !== 0) return;
    const next = force ?? (this.mode === 'blast' ? 'build' : 'blast');
    if (next === this.mode) return;
    this.mode = next;
    this.aiming = false;
    this.painting = false;
    if (this.mode === 'build') {
      const w = this.activeWorm;
      this.updateBuildGhost(w.x + w.facing * GRID * 1.4, w.y - 18);
      this.audio.play('ui');
    } else {
      this.buildGhost = null;
    }
    this.ui?.setMode(this.mode);
  }

  selectWeapon(id) {
    if (!WEAPONS[id] || this.state !== 'aim' || this.activeTeam !== 0) return;
    this.weapon = id;
    if (this.mode === 'build') { this.mode = 'blast'; this.buildGhost = null; this.ui?.setMode(this.mode); }
    this.audio.play('ui');
    this.ui?.syncWeapon();
  }

  selectBuild(type) {
    if (!BUILD_ORDER.includes(type)) return;
    this.buildType = type;
    this.audio.play('ui');
    this.ui?.syncWeapon();
    this.updateBuildGhost(this.pointer.x, this.pointer.y);
  }

  cycleMaterial() {
    const keys = Object.keys(MATERIALS);
    const i = keys.indexOf(this.material);
    this.material = keys[(i + 1) % keys.length];
    this.rampDir = this.rampDir || 1;
    this.audio.play('ui');
    this.ui?.syncWeapon();
    this.updateBuildGhost(this.pointer.x, this.pointer.y);
  }

  rotateRamp() {
    this.rampDir *= -1;
    this.audio.play('ui');
    this.updateBuildGhost(this.pointer.x, this.pointer.y);
    this.ui?.syncWeapon();
  }

  jump() {
    if (this.state !== 'aim' || this.activeTeam !== 0) return;
    const w = this.activeWorm;
    if (!w?.alive || !w.onGround || w.jumps <= 0) return;
    w.vy = -372;
    w.jumps--;
    w.onGround = false;
    this.audio.play('jump');
    this.fx.puff(w.x, w.y, '#c9b28a', 4, 26);
  }

  setKey(dir, down) {
    if (dir === 'left') this.keys.left = down;
    if (dir === 'right') this.keys.right = down;
  }

  /* --------------------------------------------------------------- building */
  buildCost(type = this.buildType, material = this.material) {
    return Math.max(3, Math.round(MATERIALS[material].cost * BUILD_COST[type]));
  }

  makePiece(type, gx, gy, team, material, dir) {
    return new Piece({ type, gx, gy, material, team, dir, t: this.time });
  }

  pieceAt(x, y) {
    for (const p of this.pieces) {
      if (!p.dead && p.contains(x, y)) return p;
    }
    return null;
  }

  pieceTopAt(x, maxY) {
    let best = null;
    for (const p of this.pieces) {
      if (p.dead) continue;
      const t = p.topAt(x, maxY);
      if (t !== null && (best === null || t > best)) best = t;
    }
    return best;
  }

  walkSurface(x, maxY) {
    let surface = this.terrain.surfaceBelow(x, maxY);
    const pt = this.pieceTopAt(x, maxY);
    if (pt !== null && (surface === null || pt > surface)) surface = pt;
    return surface;
  }

  hasSupport(piece) {
    const w = this.activeWorm;
    if (w && w.team === piece.team) {
      const c = piece.center();
      if (Math.hypot(c.x - w.x, c.y - (w.y - 20)) < 92) return true;
    }
    for (const s of piece.solids) {
      for (let x = s.x; x <= s.x + s.w; x += 6) {
        if (this.terrain.solidAt(x, s.y - 2) || this.terrain.solidAt(x, s.y + s.h + 2)) return true;
        if (this.terrain.solidAt(x - 2, s.y + s.h / 2) || this.terrain.solidAt(x + s.w + 2, s.y + s.h / 2)) return true;
      }
      for (let y = s.y; y <= s.y + s.h; y += 6) {
        if (this.terrain.solidAt(s.x - 2, y) || this.terrain.solidAt(s.x + s.w + 2, y)) return true;
      }
    }
    for (const s of piece.solids) {
      const pts = [
        [s.x + s.w / 2, s.y - 2], [s.x + s.w / 2, s.y + s.h + 2],
        [s.x - 2, s.y + s.h / 2], [s.x + s.w + 2, s.y + s.h / 2]
      ];
      for (const [x, y] of pts) {
        if (this.pieceAt(x, y)) return true;
        if (this.terrain.solidAt(x, y)) return true;
      }
    }
    return false;
  }

  validateGhost(gx, gy) {
    const w = this.activeWorm;
    if (!w) return { valid: false, reason: 'NO WORM' };
    if (gx < 0 || gy < 0 || gx >= WORLD.w / GRID || gy >= WORLD.h / GRID) return { valid: false, reason: 'OUT OF BOUNDS' };
    if (this.mode !== 'build') return { valid: false, reason: '' };
    const piece = this.makePiece(this.buildType, gx, gy, 0, this.material, this.rampDir);
    const c = piece.center();
    if (Math.hypot(c.x - w.x, c.y - (w.y - 22)) > 252) return { valid: false, reason: 'TOO FAR' };
    if (c.y > this.waterLevel + 18) return { valid: false, reason: 'UNDERWATER' };
    if (this.pieces.some(p => !p.dead && p.gx === gx && p.gy === gy && p.type === this.buildType)) {
      return { valid: false, reason: 'ALREADY BUILT' };
    }
    for (const worm of this.worms) {
      if (!worm.alive) continue;
      for (const s of piece.solids) {
        if (worm.x + 15 > s.x && worm.x - 15 < s.x + s.w && worm.y > s.y - 12 && worm.y - 50 < s.y + s.h) {
          return { valid: false, reason: 'BLOCKS A WORM' };
        }
      }
    }
    if (!this.hasSupport(piece)) return { valid: false, reason: 'NEEDS SUPPORT' };
    const cost = this.buildCost();
    if (this.mats[0] < cost) return { valid: false, reason: 'NOT ENOUGH MATS' };
    return { valid: true, reason: '', piece, cost };
  }

  updateBuildGhost(wx, wy) {
    if (this.mode !== 'build') { this.buildGhost = null; return; }
    const gx = Math.floor(clamp(wx, 0, WORLD.w - 1) / GRID);
    const gy = Math.floor(clamp(wy, 0, WORLD.h - 1) / GRID);
    const check = this.validateGhost(gx, gy);
    this.buildGhost = {
      gx, gy, type: this.buildType, material: this.material, dir: this.rampDir,
      valid: check.valid, reason: check.reason, cost: check.cost ?? this.buildCost()
    };
  }

  buildAtGhost() {
    if (!this.buildGhost || this.state !== 'aim' || this.activeTeam !== 0 || this.mode !== 'build') return false;
    const key = `${this.buildGhost.gx},${this.buildGhost.gy},${this.buildType}`;
    if (key === this.lastPaintCell) return false;
    this.lastPaintCell = key;
    return this.tryPlace(this.buildGhost.gx, this.buildGhost.gy, {
      team: 0, material: this.material, type: this.buildType, dir: this.rampDir, actor: this.activeWorm
    });
  }

  tryPlace(gx, gy, opts = {}) {
    const team = opts.team ?? 0;
    const material = opts.material ?? 'wood';
    const type = opts.type ?? 'wall';
    const dir = opts.dir ?? 1;
    if (gx < 0 || gy < 0 || gx >= WORLD.w / GRID || gy >= WORLD.h / GRID) return false;
    const piece = this.makePiece(type, gx, gy, team, material, dir);
    if (this.pieces.some(p => !p.dead && p.gx === gx && p.gy === gy && p.type === type)) return false;
    const c = piece.center();
    if (c.y > this.waterLevel + 14) return false;
    const actor = opts.actor ?? (team === this.activeTeam ? this.activeWorm : null);
    if (actor && actor.team === team) {
      if (Math.hypot(c.x - actor.x, c.y - (actor.y - 22)) > 252) return false;
    }
    for (const worm of this.worms) {
      if (!worm.alive) continue;
      for (const s of piece.solids) {
        if (worm.x + 14 > s.x && worm.x - 14 < s.x + s.w && worm.y > s.y - 12 && worm.y - 48 < s.y + s.h) return false;
      }
    }
    if (!opts.skipSupport && !this.hasSupport(piece)) return false;
    const cost = Math.max(3, Math.round(MATERIALS[material].cost * BUILD_COST[type]));
    if (this.mats[team] < cost) {
      if (!opts.silent) {
        this.showToast('NOT ENOUGH MATS', 'bad', 900);
        this.audio.play('denied');
      }
      return false;
    }
    this.mats[team] -= cost;
    this.pieces.push(piece);
    if (this.pieces.length > 160) {
      const idx = this.pieces.findIndex(p => p.dead);
      if (idx >= 0) this.pieces.splice(idx, 1);
    }
    this.fx.buildPop(c.x, c.y, team === 0 ? '120,215,255' : '220,150,255');
    this.fx.shake = Math.min(8, this.fx.shake + 1.4);
    this.audio.play('build');
    if (!opts.silent) {
      this.ui?.syncMats();
      this.updateBuildGhost(this.pointer.x, this.pointer.y);
    } else {
      this.ui?.syncMats();
    }
    return true;
  }

  onPieceDestroyed(piece) {
    const c = piece.center();
    const mat = MATERIALS[piece.material];
    this.fx.debris(c.x, c.y, mat.dust, 16, 300);
    this.fx.puff(c.x, c.y, '#d6c9b2', 6, 50);
    this.audio.play('buildBreak');
    this.fx.shake = Math.min(18, this.fx.shake + 3);
  }

  /* --------------------------------------------------------------- combat */
  fireActive() {
    if (this.state !== 'aim' || this.activeTeam !== 0 || this.mode !== 'blast' || !this.activeWorm?.alive) return;
    const w = this.activeWorm;
    this.fireWeapon(w, w.aimAngle, w.aimPower, this.weapon);
  }

  aiFire(plan) {
    if (this.state !== 'ai' || !this.activeWorm?.alive) return;
    this.fireWeapon(this.activeWorm, plan.angle, plan.power, plan.weapon);
  }

  fireWeapon(shooter, angle, power, weapon) {
    if (!shooter?.alive) return;
    this.aiming = false;
    this.painting = false;
    this.buildGhost = null;
    shooter.shots++;
    shooter.aimAngle = angle;
    shooter.aimPower = power;
    shooter.facing = Math.cos(angle) >= 0 ? 1 : -1;
    const muzzle = shooter.muzzle(angle);
    this.fx.muzzle(muzzle.x, muzzle.y, angle);
    this.lastHitPoint = null;

    if (weapon === 'shotgun') {
      this.fireShotgun(shooter, angle, power, muzzle);
      this.audio.play('shotgun');
      this.fx.shake = Math.min(14, this.fx.shake + 4.5);
      this.state = 'firing';
      this.firingTimer = 0.62;
      this.settleTimer = 1.25;
    } else {
      const p = new Projectile({
        type: weapon, owner: shooter, team: shooter.team,
        x: muzzle.x, y: muzzle.y, angle, power, wind: this.windAccel
      });
      this.projectiles.push(p);
      this.audio.play(weapon === 'grenade' ? 'throw' : 'shoot');
      this.fx.shake = Math.min(12, this.fx.shake + (weapon === 'grenade' ? 2 : 3.5));
      this.state = 'firing';
      this.firingTimer = 0.28;
      this.settleTimer = 1.45;
    }
    // Recoil kick
    shooter.vx -= Math.cos(angle) * 26;
    shooter.recoil = 1;
    this.ui?.hideAimHint();
    this.ui?.syncAll();
  }

  fireShotgun(shooter, angle, power, muzzle) {
    const range = 390 + power * 210;
    const pellets = 7;
    for (let i = 0; i < pellets; i++) {
      const a = angle + (i - (pellets - 1) / 2) * 0.047 + rand(0.018, -0.018);
      const dx = Math.cos(a), dy = Math.sin(a);
      let hitX = muzzle.x + dx * range, hitY = muzzle.y + dy * range;
      let hitWorm = null, hitPiece = null;
      const step = 4;
      for (let d = 10; d < range; d += step) {
        const x = muzzle.x + dx * d, y = muzzle.y + dy * d;
        if (x < 0 || x > WORLD.w || y < 0) { hitX = x; hitY = y; break; }
        if (y > this.waterLevel) { hitX = x; hitY = y; break; }
        let wormHit = null;
        for (const w of this.worms) {
          if (!w.alive) continue;
          if (dist2(x, y, w.cx, w.cy) < 17 * 17) { wormHit = w; break; }
        }
        if (wormHit) { hitWorm = wormHit; hitX = x; hitY = y; break; }
        const piece = this.pieceAt(x, y);
        if (this.terrain.solidAt(x, y) || piece) {
          hitPiece = piece;
          hitX = x; hitY = y;
          break;
        }
        let crate = null;
        for (const c of this.crates) if (c.alive && dist2(x, y, c.x, c.y - 12) < 17 * 17) { crate = c; break; }
        if (crate) { this.collectCrate(crate, shooter.team); hitX = x; hitY = y; break; }
      }
      this.fx.tracer(muzzle.x, muzzle.y, hitX, hitY, '#ffe0a3', 2);
      if (hitWorm) {
        const fall = 1 - clamp(Math.hypot(hitX - muzzle.x, hitY - muzzle.y) / range, 0, 1) * 0.35;
        hitWorm.hurt(10.5 * fall, this);
        hitWorm.vx += dx * 55;
        hitWorm.vy -= 60;
        this.fx.text(hitWorm.x, hitWorm.y - 66, '-' + Math.round(10.5 * fall), '#ffe66d', 15);
        this.fx.puff(hitX, hitY, '#7ee081', 4, 24);
        this.audio.play('hurt');
      } else if (hitPiece) {
        hitPiece.damage(26, this);
        this.fx.puff(hitX, hitY, MATERIALS[hitPiece.material].dust, 3, 26);
        this.pieces = this.pieces.filter(p => !p.dead);
      } else {
        this.terrain.carve(hitX, hitY, 9 + rand(4));
        this.fx.puff(hitX, hitY, '#9a6a3e', 3, 18);
      }
    }
  }

  simulateShot(shooter, angle, power, type = 'bazooka') {
    let x = shooter.muzzle(angle).x;
    let y = shooter.muzzle(angle).y;
    const speed = type === 'grenade' ? 300 + power * 330 : 290 + power * 410;
    let vx = Math.cos(angle) * speed, vy = Math.sin(angle) * speed;
    const dt = 0.018;
    for (let t = 0; t < 6; t += dt) {
      vx += this.windAccel * dt;
      vy += GRAVITY * dt;
      const nx = x + vx * dt, ny = y + vy * dt;
      if (nx < 0 || nx > WORLD.w || ny < -200) return { x: nx, y: ny, out: true };
      if (ny > this.waterLevel) return { x: nx, y: ny, water: true };
      for (const w of this.worms) {
        if (!w.alive || w === shooter) continue;
        if (dist2(nx, ny, w.cx, w.cy) < 17 * 17) return { x: nx, y: ny, worm: w };
      }
      if (this.terrain.solidAt(nx, ny)) return { x: nx, y: ny };
      const piece = this.pieceAt(nx, ny);
      if (piece) return { x: nx, y: ny, piece };
      x = nx; y = ny;
    }
    return { x, y, timeout: true };
  }

  lineOfSight(a, b) {
    const d = Math.hypot(b.x - a.x, b.y - a.y);
    const steps = Math.ceil(d / 6);
    for (let i = 1; i < steps; i++) {
      const t = i / steps;
      const x = lerp(a.x, b.x, t), y = lerp(a.y, b.y, t);
      if (this.terrain.solidAt(x, y) || this.pieceAt(x, y)) return false;
    }
    return true;
  }

  updateProjectiles(dt) {
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.age += dt;
      if (p.type === 'grenade') {
        p.fuse -= dt;
        if (p.fuse <= 0) {
          this.detonate(p, p.x, p.y);
          this.projectiles.splice(i, 1);
          continue;
        }
      }
      const steps = Math.max(1, Math.ceil(dt / 0.006));
      const sdt = dt / steps;
      let dead = false;
      for (let s = 0; s < steps && !dead; s++) {
        const px = p.x, py = p.y;
        p.vx += p.wind * sdt;
        p.vy += GRAVITY * sdt;
        const nx = p.x + p.vx * sdt, ny = p.y + p.vy * sdt;

        if (nx < -20 || nx > WORLD.w + 20 || ny < -300) {
          this.projectiles.splice(i, 1);
          dead = true;
          break;
        }
        if (ny > this.waterLevel) {
          this.fx.splash(nx, this.waterLevel, 20);
          this.audio.play('splash');
          this.projectiles.splice(i, 1);
          dead = true;
          break;
        }

        let directWorm = null;
        if (p.age > 0.07) {
          for (const w of this.worms) {
            if (!w.alive) continue;
            if (dist2(nx, ny, w.cx, w.cy) < 15 * 15) { directWorm = w; break; }
          }
        }
        if (directWorm) {
          p.x = nx; p.y = ny;
          this.detonate(p, nx, ny);
          this.projectiles.splice(i, 1);
          dead = true;
          break;
        }

        const terrainHit = this.terrain.solidAt(nx, ny);
        const pieceHit = this.pieceAt(nx, ny);
        if (terrainHit || pieceHit) {
          if (p.type === 'bazooka') {
            p.x = nx; p.y = ny;
            this.detonate(p, nx, ny);
            this.projectiles.splice(i, 1);
            dead = true;
            break;
          }
          const solidX = this.terrain.solidAt(px, ny) || this.pieceAt(px, ny);
          const solidY = this.terrain.solidAt(nx, py) || this.pieceAt(nx, py);
          if (solidY) {
            p.vy = -Math.abs(p.vy) * 0.44;
            p.y = py - 1.5;
            p.vx *= 0.8;
          }
          if (solidX) {
            p.vx = -p.vx * 0.52;
            p.x = px - Math.sign(p.vx || 1) * 1.5;
          }
          if (!solidX && !solidY) {
            p.vx *= -0.42; p.vy *= -0.42;
            p.x = px; p.y = py;
          }
          p.bounces++;
          this.fx.puff(nx, ny, '#c7b292', 5, 22);
          this.audio.play('land');
          if (p.bounces >= 6) {
            this.detonate(p, nx, ny);
            this.projectiles.splice(i, 1);
            dead = true;
            break;
          }
          p.x = clamp(p.x, 3, WORLD.w - 3);
          p.y = Math.min(p.y, this.waterLevel - 3);
          continue;
        }
        p.x = nx; p.y = ny;
      }
      if (dead) continue;
      p.trailTimer -= dt;
      if (p.trailTimer <= 0) {
        p.trailTimer = p.type === 'grenade' ? 0.05 : 0.022;
        this.fx.puff(p.x, p.y, p.type === 'grenade' ? '#c9bda8' : '#ddd3c2', 1, 8);
      }
    }
  }

  detonate(p, x, y) {
    this.lastHitPoint = { x, y };
    const spec = WEAPONS[p.type === 'grenade' ? 'grenade' : 'bazooka'];
    this.explode(x, y, spec.radius, spec.damage, p.team, p.owner);
  }

  explode(x, y, radius, damage, team, owner) {
    this.lastHitPoint = { x, y };
    this.terrain.carve(x, y, radius * 1.02);
    this.fx.explode(x, y, radius, {
      fire: team === 0 ? '#ffb347' : '#c99cff',
      smoke: '#4a4440',
      dirt: '#7d532f'
    });
    this.audio.play('explode');

    const pieces = this.pieces.slice();
    for (const piece of pieces) {
      if (piece.dead) continue;
      const c = piece.center();
      const d = Math.hypot(c.x - x, c.y - y);
      if (d < radius + 42) {
        const fall = clamp(1 - d / (radius + 42), 0, 1);
        piece.damage(damage * 1.72 * (0.4 + fall * 0.8) + 12, this);
      }
    }
    this.pieces = this.pieces.filter(p => !p.dead);

    for (const w of this.worms) {
      if (!w.alive) continue;
      const d = Math.hypot(w.cx - x, w.cy - y);
      if (d < radius + 26) {
        const fall = clamp(1 - d / (radius + 30), 0, 1);
        let dmg = damage * (0.36 + fall * 0.68);
        if (w === owner) dmg *= 0.66;
        dmg = Math.max(6, Math.round(dmg * rand(1.06, 0.94)));
        w.hurt(dmg, this);
        const nx = d > 1 ? (w.cx - x) / d : 0;
        const ny = d > 1 ? (w.cy - y) / d : -1;
        const force = 130 + damage * 3.2 * (0.5 + fall);
        w.vx += nx * force;
        w.vy += ny * force - 120;
        w.onGround = false;
        this.fx.text(w.x + rand(10, -10), w.y - 72, '-' + dmg, w.team === 0 ? '#ffe66d' : '#e6b3ff', 19);
        this.fx.puff(w.cx, w.cy, '#8b7a5c', 5, 32);
        this.audio.play('hurt');
      }
    }
    for (const crate of this.crates) {
      if (!crate.alive) continue;
      if (Math.hypot(crate.x - x, crate.y - 14 - y) < radius + 54) {
        this.collectCrate(crate, team);
      }
    }
    this.checkWaterDeaths();
  }

  collectCrate(crate, team) {
    if (!crate.alive) return;
    crate.alive = false;
    crate.takenBy = team;
    this.mats[team] = Math.min(150, this.mats[team] + 26);
    this.fx.text(crate.x, crate.y - 34, '+26 MATS', team === 0 ? '#ffe66d' : '#c9a8ff', 16);
    this.fx.puff(crate.x, crate.y - 12, '#ffd166', 10, 60);
    this.fx.buildPop(crate.x, crate.y - 10, '255,210,100');
    this.audio.play('pickup');
    this.showToast(team === 0 ? '+26 MATS SECURED' : 'SYNDICATE LOOTED A CRATE', team === 0 ? 'good' : 'bad', 1400);
    this.ui?.syncMats();
  }

  onWormDeath(worm) {
    if (worm.drowned) {
      this.fx.splash(worm.x, this.waterLevel, 34);
      this.audio.play('splash');
    } else {
      this.fx.explode(worm.x, worm.y - 20, 30, { fire: worm.team === 0 ? '#ffb347' : '#d1a3ff', smoke: '#5a5550', dirt: '#8a6a4a' });
      this.fx.debris(worm.x, worm.y - 25, TEAM_COLORS[worm.team], 18, 280);
      this.audio.play('hurt');
    }
    this.fx.text(worm.x, worm.y - 84, 'K.O.', '#ff4d6d', 24);
    this.fx.shake = Math.min(20, this.fx.shake + 6);
    this.showToast(`${worm.name} IS OUT`, 'bad', 1600);
    this.ui?.syncAll();
  }

  checkWaterDeaths() {
    for (const w of this.worms) {
      if (!w.alive) continue;
      if (w.y > this.waterLevel + 3) {
        w.drowned = true;
        w.hp = 0;
        w.alive = false;
        w.deathTimer = 0;
        this.onWormDeath(w);
      }
    }
  }

  /* ------------------------------------------------------------- worm sim */
  updateWorms(dt) {
    for (const w of this.worms) {
      if (!w.alive) { w.deathTimer = Math.min(3, w.deathTimer + dt); continue; }
      w.hurtFlash = Math.max(0, w.hurtFlash - dt);
      w.recoil = Math.max(0, w.recoil - dt * 4);

      const controlled = this.state === 'aim' && this.activeTeam === 0 && this.activeWorm === w;
      let moving = false;
      if (controlled) {
        const dir = (this.keys.right ? 1 : 0) - (this.keys.left ? 1 : 0);
        if (dir && w.fuel > 0) {
          w.facing = dir;
          w.walkTime += dt * 1.9;
          w.fuel = Math.max(0, w.fuel - dt);
          this.moveWormX(w, dir * 126 * dt);
          moving = true;
        }
      }
      if (!moving) {
        if (Math.abs(w.vx) > 1.2) {
          this.moveWormX(w, w.vx * dt);
        }
        w.vx *= Math.pow(0.04, dt);
      }

      // Unstick from terrain after an explosion.
      if (this.terrain.solidAt(w.x, w.y - 8)) {
        w.y -= 90 * dt;
        w.vy = Math.min(w.vy, 0);
        continue;
      }

      const prevY = w.y;
      w.vy += 1180 * dt;
      w.y += w.vy * dt;
      if (w.vy > 0) {
        const surface = this.fallSurface(w.x, prevY + 2, w.y + 2);
        if (surface !== null && w.y >= surface) {
          if (w.vy > 410) {
            this.audio.play('land');
            this.fx.puff(w.x, surface, '#c9b28a', 4, 22);
          }
          w.y = surface;
          w.vy = 0;
          w.onGround = true;
        } else {
          w.onGround = false;
        }
      } else {
        w.onGround = false;
      }
      if (w.y > this.waterLevel + 3) {
        w.drowned = true;
        w.hp = 0;
        w.alive = false;
        w.deathTimer = 0;
        this.onWormDeath(w);
      }
    }
  }

  fallSurface(x, fromY, toY) {
    if (toY <= fromY) return null;
    let best = this.terrain.surfaceBetween(x, fromY, toY);
    for (const p of this.pieces) {
      if (p.dead) continue;
      for (const s of p.solids) {
        if (x < s.x - 2 || x > s.x + s.w + 2) continue;
        if (s.y >= fromY - 2 && s.y <= toY + 2) {
          if (best === null || s.y < best) best = s.y;
        }
      }
    }
    return best;
  }

  moveWormX(w, dx) {
    if (!dx) return;
    const nx = clamp(w.x + dx, 16, WORLD.w - 16);
    const surface = this.walkSurface(nx, w.y + STEP);
    if (surface !== null && w.y - surface > STEP) {
      w.vx *= -0.15;
      return;
    }
    const feet = surface ?? w.y;
    for (const yy of [feet - 7, feet - 19, feet - 33]) {
      if (this.terrain.solidAt(nx, yy) || this.pieceAt(nx, yy)) {
        w.vx *= -0.1;
        return;
      }
    }
    w.x = nx;
    if (surface !== null && Math.abs(surface - w.y) <= STEP + 1) w.y = surface;
    if (feet < w.y) w.y = feet;
  }

  /* --------------------------------------------------------------- crates */
  updateCrates(dt) {
    for (const c of this.crates) {
      if (!c.alive) continue;
      c.bob += dt * 2.4;
      const ground = this.terrain.solidAt(c.x, c.y + 12) || this.pieceAt(c.x, c.y + 12);
      if (!ground) {
        c.vy += 900 * dt;
        const prev = c.y;
        c.y += c.vy * dt;
        const surface = this.fallSurface(c.x, prev, c.y);
        if (surface !== null && c.y >= surface) { c.y = surface; c.vy = 0; }
      } else {
        c.vy = 0;
      }
      if (c.y > this.waterLevel + 4) {
        c.alive = false;
        this.fx.splash(c.x, this.waterLevel, 12);
        this.audio.play('splash');
      }
    }
  }

  /* ------------------------------------------------------------ turn state */
  update(dt) {
    if (this.paused) return;
    dt = Math.min(dt, 0.033);
    this.time += dt;
    this.fx.update(dt);
    for (const p of this.pieces) {
      if (p.flash > 0) p.flash = Math.max(0, p.flash - dt);
      p.sinceHit += dt;
    }

    if (this.state === 'demo') {
      this.updateCamera(dt);
      this.ui?.syncTimer?.();
      return;
    }

    if (this.state === 'over') {
      this.updateWorms(dt);
      this.updateCrates(dt);
      this.effectsTimer -= dt;
      if (this.effectsTimer <= 0) {
        this.effectsTimer = 0.8;
        const x = rand(1500, 300), y = rand(500, 220);
        this.fx.explode2?.(x, y);
      }
      this.updateCamera(dt);
      return;
    }

    this.matchTime += dt;
    this.updateWorms(dt);
    this.updateCrates(dt);
    if (this.state === 'firing') this.updateProjectiles(dt);

    if (this.state === 'aim') {
      this.timeLeft -= dt;
      const sec = Math.ceil(this.timeLeft);
      if (sec <= 9 && sec !== this.lastTickSecond && sec > 0) {
        this.lastTickSecond = sec;
        this.audio.play('tick');
      }
      if (this.timeLeft <= 0) {
        this.timeLeft = 0;
        this.showToast("TIME'S UP", 'bad', 900);
        if (this.mode === 'build') this.toggleMode('blast');
        this.fireActive();
      }
      if (this.activeWorm && this.activeWorm.fuel <= 0 && (this.keys.left || this.keys.right)) {
        this.keys.left = false; this.keys.right = false;
      }
    }

    if (this.state === 'ai') {
      this.ai.update(dt);
    }

    if (this.state === 'firing') {
      this.firingTimer -= dt;
      if (this.projectiles.length === 0 && this.firingTimer <= 0) {
        this.state = 'settle';
        this.settleTimer = 1.35;
        this.checkWaterDeaths();
      }
    } else if (this.state === 'settle') {
      this.settleTimer -= dt;
      if (this.settleTimer <= 0) {
        this.checkWaterDeaths();
        if (this.checkWin()) return;
        this.advanceTurn();
      }
    }

    this.updateCamera(dt);
    this.ui?.sync();
  }

  advanceTurn() {
    if (this.state === 'over') return;
    if (this.checkWin()) return;
    this.activeTeam = 1 - this.activeTeam;
    if (this.activeTeam === 0) {
      this.round++;
      if (this.round >= 3 && this.round % 2 === 1) this.raiseWater();
      if (this.state === 'over' || this.checkWin()) return;
      this.checkWaterDeaths();
    }
    this.startTurn(this.activeTeam);
  }

  raiseWater() {
    this.waterLevel = Math.max(762, this.waterLevel - 20);
    this.fx.flash = 0.25;
    this.fx.flashColor = '150,80,255';
    this.fx.shake = Math.min(20, this.fx.shake + 5);
    this.audio.play('storm');
    this.showToast('STORM SURGE · THE WATER IS RISING', 'bad', 2200);
    this.ui?.banner('STORM SURGE', 'THE WATER IS RISING', 'Low ground is about to disappear.', '#b06bff', 2300);
    this.checkWaterDeaths();
  }

  checkWin() {
    if (this.state === 'over') return true;
    const a0 = this.aliveCount(0), a1 = this.aliveCount(1);
    if (a0 === 0 && a1 === 0) { this.finishMatch(-1); return true; }
    if (a0 === 0) { this.finishMatch(1); return true; }
    if (a1 === 0) { this.finishMatch(0); return true; }
    return false;
  }

  finishMatch(winner) {
    if (this.state === 'over') return;
    this.winner = winner;
    this.state = 'over';
    this.effectsTimer = 0.5;
    this.ui?.showResult(winner);
    this.ui?.syncAll();
    this.audio.play(winner === 0 ? 'victory' : winner === 1 ? 'defeat' : 'hurt');
    if (winner === 0) {
      for (let i = 0; i < 5; i++) {
        const w = this.activeWorm && this.activeWorm.alive ? this.activeWorm : this.worms.find(w => w.team === 0 && w.alive);
        if (w) this.fx.text(w.x + rand(60, -60), w.y - 70 - i * 12, ['VICTORY!', 'GG!', 'ROYALE!'][i % 3], ['#ffe66d', '#ff9f1c', '#7ee081'][i % 3], 26);
      }
    }
  }

  endTurn() {
    if (this.state !== 'aim' || this.activeTeam !== 0) return;
    this.aiming = false;
    this.painting = false;
    this.state = 'between';
    this.showToast('TURN PASSED', '', 900);
    this.audio.play('ui');
    this.advanceTurn();
  }

  showToast(text, type = '', duration = 1500) {
    this.ui?.toast(text, type, duration);
  }

  /* -------------------------------------------------------- debug helpers */
  debugBuild(gx, gy, type = 'wall', material = 'wood') {
    return this.tryPlace(gx, gy, { team: 0, type, material, dir: 1, skipSupport: true });
  }

  debugHit(gx, gy) {
    this.explode(gx * GRID + 24, gy * GRID + 24, 60, 54, 1, null);
  }
}

export { WEAPONS, WEAPON_ORDER, BUILD_ORDER, MATERIALS };

import {
  WORLD, GRID, GRAVITY, TEAM_COLORS, clamp, lerp, TAU, hash2
} from './core.js';
import { MATERIALS } from './pieces.js';

const CLOUDS = [
  { x: 160, y: 150, s: 1.15, sp: 4 },
  { x: 620, y: 108, s: 0.8, sp: 2 },
  { x: 1040, y: 196, s: 1.35, sp: 5 },
  { x: 1450, y: 120, s: 0.65, sp: 3 },
  { x: 1780, y: 240, s: 0.9, sp: 1.5 },
  { x: 380, y: 300, s: 0.55, sp: 6 },
  { x: 1280, y: 320, s: 0.45, sp: 4.5 }
];

export class Renderer {
  constructor(game) {
    this.game = game;
    this.ctx = game.ctx;
    this.confetti = null;
  }

  render() {
    const g = this.game;
    const ctx = this.ctx;
    const v = g.view;
    ctx.save();
    ctx.clearRect(0, 0, v.w, v.h);
    this.drawSky();

    const shake = g.fx.shake;
    const sx = shake ? (Math.random() - 0.5) * shake : 0;
    const sy = shake ? (Math.random() - 0.5) * shake : 0;

    ctx.save();
    ctx.translate(v.cx + sx, v.cy + sy);
    ctx.scale(v.zoom, v.zoom);
    ctx.translate(-g.camX, -g.camY);

    this.drawBackdropObjects();
    g.terrain.draw(ctx);
    this.drawWater(ctx);
    for (const p of g.pieces) p.draw(ctx, g.time);
    this.drawCrates(ctx);
    for (const w of g.worms) this.drawWorm(ctx, w);
    for (const p of g.projectiles) this.drawProjectile(ctx, p);
    g.fx.drawBehind(ctx);
    if (g.state === 'aim' && g.activeWorm?.alive) {
      if (g.mode === 'build') this.drawBuildMode(ctx);
      else this.drawAim(ctx);
    }
    g.fx.draw(ctx);
    this.drawBuildStatus(ctx);
    ctx.restore();

    this.drawScreenEffects();
    ctx.restore();
  }

  /* ---------------------------------------------------------------- sky */
  drawSky() {
    const g = this.game;
    const ctx = this.ctx;
    const v = g.view;
    const t = g.time;
    const grad = ctx.createLinearGradient(0, 0, v.w * 0.35, v.h);
    grad.addColorStop(0, '#131c45');
    grad.addColorStop(0.28, '#2d2c60');
    grad.addColorStop(0.52, '#71436e');
    grad.addColorStop(0.7, '#c9666a');
    grad.addColorStop(0.84, '#f0985f');
    grad.addColorStop(1, '#ffd073');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, v.w, v.h);

    // stars
    for (let i = 0; i < 26; i++) {
      const x = hash2(i, 1, 9) * v.w;
      const y = hash2(i, 2, 5) * v.h * 0.3;
      const tw = 0.35 + 0.65 * Math.abs(Math.sin(t * 0.7 + i));
      ctx.globalAlpha = tw * 0.4 * (1 - y / (v.h * 0.45));
      ctx.fillStyle = '#fff';
      ctx.fillRect(x, y, 1.5, 1.5);
    }
    ctx.globalAlpha = 1;

    // sun
    const sun = g.worldToScreen(1310, 330);
    const sunR = 78 * v.zoom;
    const glow = ctx.createRadialGradient(sun.x, sun.y, 0, sun.x, sun.y, sunR * 4);
    glow.addColorStop(0, 'rgba(255,230,160,.48)');
    glow.addColorStop(0.32, 'rgba(255,180,100,.16)');
    glow.addColorStop(1, 'rgba(255,140,80,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(sun.x, sun.y, sunR * 4, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(255,240,190,.9)';
    ctx.beginPath(); ctx.arc(sun.x, sun.y, sunR, 0, TAU); ctx.fill();
    ctx.fillStyle = 'rgba(255,255,225,.55)';
    ctx.beginPath(); ctx.arc(sun.x, sun.y, sunR * 0.7, 0, TAU); ctx.fill();

    // clouds with parallax
    for (let i = 0; i < CLOUDS.length; i++) {
      const c = CLOUDS[i];
      const drift = (t * c.sp) % (v.w + 500);
      let x = ((c.x - g.camX * 0.16 + drift) % (v.w + 500) + v.w + 500) % (v.w + 500) - 250;
      const y = c.y - (g.camY - 550) * 0.12;
      this.cloud(x, y, c.s * v.zoom, 0.11 + (i % 3) * 0.03);
    }

    // mountain silhouettes with a subtle parallax
    const horizon = g.worldToScreen(0, 852).y;
    const off = -g.camX * 0.1;
    this.ridge(horizon + 12, 74, 0.0032, off, '#2c2a54', 0.9);
    this.ridge(horizon + 36, 108, 0.0047, off * 1.5 + 90, '#222446', 1);

    // distant floating isles
    ctx.globalAlpha = 0.32;
    ctx.fillStyle = '#24234a';
    const isleX = 240 + ((off * 0.6) % 400);
    this.distantIsle(isleX, horizon - 150, 54);
    this.distantIsle(isleX + 440, horizon - 210, 32);
    ctx.globalAlpha = 1;

    // birds
    ctx.strokeStyle = 'rgba(25,20,40,.5)';
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 4; i++) {
      const bx = ((i * 211 + t * 7) % (v.w + 100)) - 50;
      const by = 155 + (i % 3) * 43 + Math.sin(t * 1.2 + i) * 5;
      const flap = Math.sin(t * 5 + i * 2) * 3;
      ctx.beginPath();
      ctx.moveTo(bx - 6, by + flap);
      ctx.quadraticCurveTo(bx - 2, by - 2, bx, by);
      ctx.quadraticCurveTo(bx + 2, by - 2, bx + 6, by + flap);
      ctx.stroke();
    }

    // atmospheric haze
    const haze = ctx.createLinearGradient(0, horizon - 170, 0, horizon + 30);
    haze.addColorStop(0, 'rgba(255,170,120,0)');
    haze.addColorStop(0.7, 'rgba(255,170,120,.14)');
    haze.addColorStop(1, 'rgba(255,180,120,0)');
    ctx.fillStyle = haze;
    ctx.fillRect(0, horizon - 170, v.w, 200);
  }

  cloud(x, y, scale, alpha) {
    const ctx = this.ctx;
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale * 0.72);
    ctx.globalAlpha = alpha;
    ctx.fillStyle = '#ffe1d3';
    for (const [dx, dy, r] of [[0, 0, 23], [20, -8, 29], [45, 1, 20], [18, 9, 25], [-20, 6, 17]]) {
      ctx.beginPath(); ctx.arc(dx, dy, r, 0, TAU); ctx.fill();
    }
    ctx.fillStyle = 'rgba(126,100,140,.18)';
    for (const [dx, dy, r] of [[0, 8, 20], [20, 5, 24], [44, 6, 16], [17, 14, 20]]) {
      ctx.beginPath(); ctx.arc(dx, dy, r, 0, TAU); ctx.fill();
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  ridge(baseY, height, freq, off, color, alpha) {
    const ctx = this.ctx;
    const v = this.game.view;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(-40, v.h + 40);
    for (let x = -40; x <= v.w + 40; x += 24) {
      const wx = x + off;
      const y = baseY - height * (0.45 + 0.35 * Math.sin(wx * freq) + 0.2 * Math.sin(wx * freq * 2.7 + 2));
      ctx.lineTo(x, y);
    }
    ctx.lineTo(v.w + 40, v.h + 40);
    ctx.closePath();
    ctx.fill();
    ctx.globalAlpha = 1;
  }

  distantIsle(x, y, r) {
    const ctx = this.ctx;
    ctx.beginPath();
    ctx.ellipse(x, y, r, r * 0.26, 0, 0, TAU);
    ctx.moveTo(x - r, y);
    ctx.quadraticCurveTo(x, y + r * 1.5, x + r, y);
    ctx.fill();
  }

  drawBackdropObjects() {
    const g = this.game;
    const ctx = this.ctx;
    const t = g.time;
    // warm god rays
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.05;
    ctx.fillStyle = '#ffbe7a';
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      const x = 1170 + i * 44;
      ctx.moveTo(x, 260);
      ctx.lineTo(x - 150 - i * 30, 1100);
      ctx.lineTo(x - 80 - i * 25, 1100);
      ctx.lineTo(x + 22, 260);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();

    // lazy ash motes
    for (let i = 0; i < 30; i++) {
      const x = (hash2(i, 4, 8) * WORLD.w + t * (5 + (i % 4) * 3)) % WORLD.w;
      const y = 250 + ((hash2(i, 5, 7) * 780 + Math.sin(t * 0.3 + i) * 30) % 760);
      ctx.globalAlpha = 0.12 + (i % 3) * 0.05;
      ctx.fillStyle = i % 2 ? '#ffd9a1' : '#c9c0ff';
      ctx.beginPath(); ctx.arc(x, y, 1 + (i % 3) * 0.5, 0, TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* -------------------------------------------------------------- water */
  drawWater(ctx) {
    const g = this.game;
    const wl = g.waterLevel;
    const t = g.time;
    const gradient = ctx.createLinearGradient(0, wl, 0, WORLD.h);
    gradient.addColorStop(0, 'rgba(44,145,164,.74)');
    gradient.addColorStop(0.35, 'rgba(22,96,128,.82)');
    gradient.addColorStop(1, 'rgba(8,38,70,.94)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, wl, WORLD.w, WORLD.h - wl + 10);

    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(140,235,255,.22)';
    for (let i = 0; i < 3; i++) {
      ctx.lineWidth = 1.2 + i;
      ctx.beginPath();
      for (let x = -20; x <= WORLD.w + 20; x += 20) {
        const y = wl + 4 + i * 12 + Math.sin(x * 0.018 + t * (1.1 + i * 0.2) + i) * (2.5 + i);
        if (x === -20) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    // foam at coastline
    ctx.strokeStyle = 'rgba(205,250,255,.45)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let x = 0; x <= WORLD.w; x += 14) {
      const y = wl + Math.sin(x * 0.024 + t * 1.7) * 3;
      if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.restore();

    // shimmering highlights
    ctx.globalAlpha = 0.18;
    ctx.fillStyle = '#bff9ff';
    for (let i = 0; i < 22; i++) {
      const x = (hash2(i, 7, 3) * WORLD.w + t * 8) % WORLD.w;
      const y = wl + 10 + hash2(i, 8, 6) * (WORLD.h - wl - 20);
      ctx.fillRect(x, y, 10 + (i % 3) * 5, 1.2);
    }
    ctx.globalAlpha = 1;
  }

  /* ------------------------------------------------------------- crates */
  drawCrates(ctx) {
    const g = this.game;
    for (const c of g.crates) {
      if (!c.alive) continue;
      const bob = Math.sin(g.time * 2.2 + c.bob) * 1.8;
      const y = c.y + bob;
      ctx.save();
      ctx.globalAlpha = 0.24;
      ctx.fillStyle = '#ffe66d';
      const beam = ctx.createLinearGradient(0, y - 90, 0, y);
      beam.addColorStop(0, 'rgba(255,230,109,0)');
      beam.addColorStop(0.7, 'rgba(255,230,109,.18)');
      beam.addColorStop(1, 'rgba(255,230,109,.4)');
      ctx.fillStyle = beam;
      ctx.fillRect(c.x - 9, y - 90, 18, 88);
      ctx.restore();

      ctx.save();
      ctx.fillStyle = 'rgba(0,0,0,.25)';
      ctx.beginPath(); ctx.ellipse(c.x, c.y + 1, 17, 5, 0, 0, TAU); ctx.fill();

      // parachute folded behind
      ctx.fillStyle = 'rgba(225,210,180,.55)';
      ctx.beginPath();
      ctx.moveTo(c.x - 16, y - 22);
      ctx.quadraticCurveTo(c.x, y - 34, c.x + 16, y - 22);
      ctx.quadraticCurveTo(c.x, y - 18, c.x - 16, y - 22);
      ctx.fill();

      // crate body
      const ch = 26, cw = 30;
      ctx.fillStyle = '#7a4c24';
      ctx.fillRect(c.x - cw / 2, y - ch, cw, ch);
      ctx.fillStyle = '#b97a38';
      ctx.fillRect(c.x - cw / 2 + 3, y - ch + 3, cw - 6, ch - 6);
      ctx.strokeStyle = '#5a3417';
      ctx.lineWidth = 2;
      ctx.strokeRect(c.x - cw / 2, y - ch, cw, ch);
      ctx.fillStyle = '#3f2a16';
      for (const dx of [-9, 0, 9]) {
        ctx.fillRect(c.x + dx - 1.5, y - ch + 4, 3, ch - 8);
      }
      ctx.fillStyle = '#ffd166';
      ctx.beginPath();
      ctx.moveTo(c.x, y - 20); ctx.lineTo(c.x + 6, y - 13); ctx.lineTo(c.x, y - 6); ctx.lineTo(c.x - 6, y - 13);
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#7a4c24';
      ctx.font = '900 8px "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('!', c.x, y - 10);

      // beacon
      const pulse = 0.5 + 0.5 * Math.sin(g.time * 4 + c.bob);
      ctx.globalAlpha = 0.5 + pulse * 0.5;
      ctx.fillStyle = '#ffe66d';
      ctx.beginPath(); ctx.arc(c.x, y - ch - 4, 2.2 + pulse, 0, TAU); ctx.fill();
      ctx.restore();
    }
  }

  /* --------------------------------------------------------------- worm */
  drawWorm(ctx, w) {
    const g = this.game;
    if (!w.alive) { this.drawGrave(ctx, w); return; }
    const t = g.time;
    const active = g.activeWorm === w && g.state !== 'demo';
    const bob = Math.sin(t * 2.6 + w.idleOffset) * (active ? 1.5 : 1);
    const walk = Math.abs(w.vx) > 10 && w.onGround ? Math.sin(w.walkTime * 2) * 2 : 0;
    const x = w.x + walk * 0.4;
    const feet = w.y + bob;
    const facing = w.facing || 1;
    const teamColor = TEAM_COLORS[w.team];
    const body = w.hurtFlash > 0.18 ? '#ffffff' : teamColor;
    const dark = w.team === 0 ? '#9c4d00' : '#5e2b9e';
    const light = w.team === 0 ? '#ffd08a' : '#d9b6ff';
    const headX = x + facing * 3;
    const headY = feet - 46 + bob * 0.4;

    // ground shadow
    ctx.globalAlpha = 0.3;
    ctx.fillStyle = '#0a0918';
    ctx.beginPath(); ctx.ellipse(x, w.y + 2, 19, 5, 0, 0, TAU); ctx.fill();
    ctx.globalAlpha = 1;

    if (active) {
      // active aura
      const pulse = 0.55 + 0.45 * Math.sin(t * 3.4);
      ctx.save();
      ctx.translate(x, w.y + 1);
      ctx.scale(1, 0.32);
      ctx.strokeStyle = teamColor;
      ctx.globalAlpha = 0.35 + pulse * 0.25;
      ctx.lineWidth = 2.5;
      ctx.setLineDash([6, 7]);
      ctx.lineDashOffset = -t * 22;
      ctx.beginPath(); ctx.arc(0, 0, 31, 0, TAU); ctx.stroke();
      ctx.restore();
      // marker chevron
      const by = w.y - 96 + Math.sin(t * 4) * 3;
      ctx.fillStyle = teamColor;
      ctx.beginPath();
      ctx.moveTo(x - 7, by - 6); ctx.lineTo(x + 7, by - 6); ctx.lineTo(x, by + 2);
      ctx.closePath(); ctx.fill();
      ctx.globalAlpha = 0.35;
      ctx.beginPath();
      ctx.moveTo(x - 4, by - 10); ctx.lineTo(x + 4, by - 10); ctx.lineTo(x, by - 6);
      ctx.closePath(); ctx.fill();
      ctx.globalAlpha = 1;
    }

    // tail and body
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.strokeStyle = dark;
    ctx.lineWidth = 19;
    ctx.beginPath();
    ctx.moveTo(x - facing * 10, feet - 6);
    ctx.quadraticCurveTo(x - facing * 7, feet - 30, headX, headY + 6);
    ctx.stroke();
    ctx.strokeStyle = body;
    ctx.lineWidth = 15;
    ctx.beginPath();
    ctx.moveTo(x - facing * 10, feet - 6);
    ctx.quadraticCurveTo(x - facing * 7, feet - 30, headX, headY + 6);
    ctx.stroke();

    // belly highlight
    ctx.strokeStyle = light;
    ctx.globalAlpha = 0.42;
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(x - facing * 13, feet - 8);
    ctx.quadraticCurveTo(x - facing * 11, feet - 28, headX - facing * 3, headY + 5);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // segment rings
    ctx.strokeStyle = dark;
    ctx.globalAlpha = 0.25;
    ctx.lineWidth = 1.4;
    for (let i = 0; i < 3; i++) {
      const yy = feet - 12 - i * 10;
      ctx.beginPath();
      ctx.moveTo(x - facing * 6, yy);
      ctx.quadraticCurveTo(x, yy - 2, x + facing * 5, yy + 1);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // head
    ctx.fillStyle = dark;
    ctx.beginPath(); ctx.ellipse(headX, headY, 17, 16, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = body;
    ctx.beginPath(); ctx.ellipse(headX, headY - 1, 14.5, 13.5, 0, 0, TAU); ctx.fill();
    // cheek
    ctx.fillStyle = 'rgba(255,110,140,.3)';
    ctx.beginPath(); ctx.ellipse(headX + facing * 7, headY + 6, 4, 2.6, 0, 0, TAU); ctx.fill();

    // eyes
    const look = Math.cos(w.aimAngle || 0) * 1.7;
    const lookY = Math.sin(w.aimAngle || 0) * 1.3;
    const ex = headX + facing * 3;
    for (const off of [-5.5, 4.5]) {
      const eyeX = ex + off;
      ctx.fillStyle = '#fffdf2';
      ctx.beginPath(); ctx.ellipse(eyeX, headY - 3, 4, 5.4, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#15182c';
      ctx.beginPath(); ctx.arc(eyeX + look * 0.75, headY - 2 + lookY * 0.7, 2.1, 0, TAU); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.85)';
      ctx.beginPath(); ctx.arc(eyeX + look * 0.75 - 0.7, headY - 3 + lookY * 0.7, 0.65, 0, TAU); ctx.fill();
    }
    // mouth
    ctx.strokeStyle = dark;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.arc(headX + facing * 4, headY + 6.5, 3.4, 0.15, Math.PI - 0.15);
    ctx.stroke();

    // helmet
    ctx.save();
    ctx.translate(headX, headY - 7);
    ctx.rotate(facing * -0.08);
    ctx.fillStyle = dark;
    ctx.beginPath();
    ctx.ellipse(0, 0, 17, 12, 0, Math.PI, TAU);
    ctx.fill();
    ctx.fillStyle = w.team === 0 ? '#ffd166' : '#7e4bc0';
    ctx.beginPath();
    ctx.ellipse(0, -1, 14.5, 10.5, 0, Math.PI, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,.25)';
    ctx.beginPath();
    ctx.ellipse(-3, -6, 8, 4, -0.25, Math.PI, TAU);
    ctx.fill();
    // brim
    ctx.fillStyle = dark;
    ctx.fillRect(-17, -1, 34, 3);
    // team flair
    if (w.team === 0) {
      ctx.fillStyle = '#7ee081';
      ctx.beginPath();
      ctx.ellipse(0, -10, 4.5, 2.6, -0.6, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = '#4d9c45'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(2, -17); ctx.stroke();
    } else {
      ctx.fillStyle = '#ffd166';
      ctx.beginPath();
      ctx.moveTo(-9, -4); ctx.lineTo(-5, -13); ctx.lineTo(0, -5);
      ctx.lineTo(5, -13); ctx.lineTo(8, -4);
      ctx.closePath(); ctx.fill();
    }
    ctx.restore();

    // weapon + arms
    const angle = w.aimAngle ?? (facing > 0 ? -0.5 : -Math.PI + 0.5);
    const mx = w.muzzle(angle).x;
    const my = w.muzzle(angle).y + bob * 0.3;
    ctx.save();
    ctx.translate(mx, my);
    ctx.rotate(angle);
    ctx.scale(1, 1);
    this.drawWeapon(ctx, g.weapon, false);
    ctx.restore();

    // arm
    ctx.strokeStyle = dark;
    ctx.lineWidth = 6.5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(x + facing * 7, feet - 29);
    ctx.quadraticCurveTo(x + facing * 16, feet - 32, mx - Math.cos(angle) * 6, my - Math.sin(angle) * 6);
    ctx.stroke();
    ctx.strokeStyle = body;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(x + facing * 7, feet - 29);
    ctx.quadraticCurveTo(x + facing * 16, feet - 32, mx - Math.cos(angle) * 6, my - Math.sin(angle) * 6);
    ctx.stroke();

    // health bar + label
    const showBar = active || w.hp < w.maxHp;
    if (showBar) {
      const bw = 42, bx = x - bw / 2, by = headY - 34;
      ctx.fillStyle = 'rgba(6,9,20,.72)';
      ctx.fillRect(bx - 2, by - 2, bw + 4, 8);
      ctx.fillStyle = 'rgba(255,255,255,.14)';
      ctx.fillRect(bx, by, bw, 4);
      const frac = w.hp / w.maxHp;
      ctx.fillStyle = frac > 0.55 ? '#7ee081' : frac > 0.25 ? '#ffd166' : '#ff4d6d';
      ctx.fillRect(bx, by, bw * frac, 4);
      ctx.fillStyle = 'rgba(255,255,255,.88)';
      ctx.font = '800 8px "Trebuchet MS", sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(w.name, x, by - 6);
    }
    ctx.globalAlpha = 1;
  }

  drawWeapon(ctx, weapon, small) {
    const scale = small ? 0.8 : 1;
    ctx.save();
    ctx.scale(scale, scale);
    if (weapon === 'bazooka') {
      ctx.fillStyle = '#3f4f3d';
      ctx.fillRect(-12, -5, 40, 10);
      ctx.fillStyle = '#748d61';
      ctx.fillRect(-10, -4, 36, 6);
      ctx.fillStyle = '#2c382b';
      ctx.fillRect(18, -7, 9, 14);
      ctx.fillStyle = '#ff9f1c';
      ctx.fillRect(26, -5.5, 5, 11);
      ctx.fillStyle = 'rgba(0,0,0,.3)';
      ctx.fillRect(-6, 4, 22, 2.5);
    } else if (weapon === 'shotgun') {
      ctx.fillStyle = '#6d4425';
      ctx.fillRect(-14, -3, 20, 9);
      ctx.fillStyle = '#8a5a30';
      ctx.fillRect(-14, -3, 9, 9);
      ctx.fillStyle = '#5c6670';
      ctx.fillRect(4, -4, 32, 7);
      ctx.fillStyle = '#8b97a3';
      ctx.fillRect(6, -3, 26, 3);
      ctx.fillStyle = '#37424c';
      ctx.fillRect(30, -3.5, 6, 6);
    } else {
      ctx.fillStyle = '#4d6b3e';
      ctx.beginPath(); ctx.arc(0, 0, 6.5, 0, TAU); ctx.fill();
      ctx.fillStyle = '#88a765';
      ctx.beginPath(); ctx.arc(-1, -1, 5, 0, TAU); ctx.fill();
      ctx.fillStyle = '#b0c894';
      ctx.fillRect(-3, -5, 6, 2);
      ctx.strokeStyle = '#8b8f96'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(5, -4, 3, 0, TAU); ctx.stroke();
    }
    ctx.restore();
  }

  drawGrave(ctx, w) {
    const g = this.game;
    const t = w.deathTimer;
    if (t < 1.1) {
      const a = 1 - t / 1.1;
      ctx.save();
      ctx.globalAlpha = a * 0.8;
      ctx.translate(w.x, w.y - 38 - t * 46);
      ctx.rotate(t * 2.4);
      ctx.scale(0.9 + t * 0.2, 0.9 + t * 0.2);
      ctx.fillStyle = TEAM_COLORS[w.team];
      ctx.beginPath(); ctx.ellipse(0, 0, 15, 18, 0, 0, TAU); ctx.fill();
      ctx.fillStyle = '#fffdf2';
      for (const ox of [-5, 4]) {
        ctx.beginPath(); ctx.arc(ox, -3, 3.4, 0, TAU); ctx.fill();
      }
      ctx.restore();
      return;
    }
    if (w.drowned) return;
    const x = w.x, y = w.y;
    ctx.save();
    ctx.fillStyle = 'rgba(0,0,0,.25)';
    ctx.beginPath(); ctx.ellipse(x, y + 1, 16, 5, 0, 0, TAU); ctx.fill();
    ctx.fillStyle = '#59606d';
    ctx.beginPath();
    ctx.moveTo(x - 12, y); ctx.lineTo(x - 12, y - 26); ctx.quadraticCurveTo(x, y - 36, x + 12, y - 26);
    ctx.lineTo(x + 12, y); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#767f8c';
    ctx.beginPath();
    ctx.moveTo(x - 9, y - 2); ctx.lineTo(x - 9, y - 25); ctx.quadraticCurveTo(x, y - 33, x + 9, y - 25);
    ctx.lineTo(x + 9, y - 2); ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(20,22,32,.55)';
    ctx.fillRect(x - 1.5, y - 26, 3, 15);
    ctx.fillRect(x - 6, y - 21, 12, 3);
    ctx.fillStyle = TEAM_COLORS[w.team];
    ctx.fillRect(x - 9, y - 8, 18, 2);
    ctx.restore();
  }

  drawProjectile(ctx, p) {
    const g = this.game;
    ctx.save();
    ctx.translate(p.x, p.y);
    if (p.type === 'grenade') {
      ctx.rotate(g.time * 7);
      ctx.fillStyle = '#3e5b39';
      ctx.beginPath(); ctx.arc(0, 0, 6.5, 0, TAU); ctx.fill();
      ctx.strokeStyle = '#2b3f27'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(-4, -3); ctx.lineTo(4, 3); ctx.moveTo(-4, 3); ctx.lineTo(4, -3); ctx.stroke();
      ctx.fillStyle = '#a5b58a';
      ctx.fillRect(-2, -9, 4, 3);
      ctx.strokeStyle = '#b9c0c6'; ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.arc(4, -7, 3, 0, TAU); ctx.stroke();
      const blink = Math.sin(g.time * 14) > 0 ? '#ff4d6d' : '#ffd166';
      ctx.fillStyle = blink;
      ctx.beginPath(); ctx.arc(0, -11, 2, 0, TAU); ctx.fill();
    } else {
      const a = Math.atan2(p.vy, p.vx);
      ctx.rotate(a);
      ctx.fillStyle = '#e6e0cf';
      ctx.fillRect(-9, -3.5, 18, 7);
      ctx.fillStyle = '#ff6b35';
      ctx.beginPath(); ctx.moveTo(9, -4); ctx.lineTo(15, 0); ctx.lineTo(9, 4); ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#a19a89';
      ctx.fillRect(-10, -3, 5, 6);
      ctx.fillStyle = 'rgba(255,220,140,.9)';
      ctx.beginPath(); ctx.arc(-12, 0, 3 + Math.random() * 2, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  /* ---------------------------------------------------------- aim/build */
  aimPreview() {
    const g = this.game;
    const w = g.activeWorm;
    if (!w) return { points: [], hit: null };
    const angle = w.aimAngle, power = w.aimPower;
    const muzzle = w.muzzle(angle);
    const points = [{ x: muzzle.x, y: muzzle.y }];
    let x = muzzle.x, y = muzzle.y;
    let hit = null;
    if (g.weapon === 'shotgun') {
      const range = 390 + power * 210;
      for (let d = 0; d <= range; d += 22) points.push({ x: muzzle.x + Math.cos(angle) * d, y: muzzle.y + Math.sin(angle) * d });
      return { points, hit: { x: muzzle.x + Math.cos(angle) * range, y: muzzle.y + Math.sin(angle) * range } };
    }
    const speed = 290 + power * 410;
    let vx = Math.cos(angle) * speed, vy = Math.sin(angle) * speed;
    const dt = 0.045;
    for (let t = 0; t < 4.2; t += dt) {
      vx += g.windAccel * dt;
      vy += GRAVITY * dt;
      x += vx * dt; y += vy * dt;
      if (y > g.waterLevel || x < 0 || x > WORLD.w || y < -100) {
        hit = { x, y };
        break;
      }
      if (g.terrain.solidAt(x, y) || g.pieceAt(x, y)) {
        hit = { x, y };
        break;
      }
      points.push({ x, y });
      if (points.length > 60) break;
    }
    if (!hit) hit = points[points.length - 1];
    return { points, hit };
  }

  drawAim(ctx) {
    const g = this.game;
    const w = g.activeWorm;
    const { points, hit } = this.aimPreview();
    const color = g.weapon === 'shotgun' ? '#ffd166' : '#ffb347';
    ctx.save();

    // dots
    for (let i = 0; i < points.length; i++) {
      const p = points[i];
      const fade = 1 - i / Math.max(1, points.length);
      const r = g.weapon === 'shotgun' ? (i % 3 === 0 ? 2.2 : 1) : 1.5 + fade * 2.6;
      ctx.globalAlpha = 0.22 + fade * 0.6;
      ctx.fillStyle = color;
      ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, TAU); ctx.fill();
      if (i < points.length - 1) {
        const n = points[i + 1];
        ctx.globalAlpha = 0.08 + fade * 0.2;
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.2;
        ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(n.x, n.y); ctx.stroke();
      }
    }

    // landing reticle
    if (hit) {
      const pulse = 0.75 + 0.25 * Math.sin(g.time * 7);
      ctx.globalAlpha = 0.85;
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.7;
      ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.arc(hit.x, hit.y, 10 * pulse, 0, TAU); ctx.stroke();
      ctx.setLineDash([]);
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      ctx.moveTo(hit.x - 15, hit.y); ctx.lineTo(hit.x - 5, hit.y);
      ctx.moveTo(hit.x + 5, hit.y); ctx.lineTo(hit.x + 15, hit.y);
      ctx.moveTo(hit.x, hit.y - 15); ctx.lineTo(hit.x, hit.y - 5);
      ctx.moveTo(hit.x, hit.y + 5); ctx.lineTo(hit.x, hit.y + 15);
      ctx.stroke();
    }

    // aim stick + drag ring
    const muzzle = w.muzzle(w.aimAngle);
    ctx.globalAlpha = 0.3;
    ctx.strokeStyle = '#ffd166';
    ctx.lineWidth = 1;
    ctx.setLineDash([3, 6]);
    ctx.beginPath(); ctx.moveTo(muzzle.x, muzzle.y); ctx.lineTo(muzzle.x + Math.cos(w.aimAngle) * w.aimPower * 150, muzzle.y + Math.sin(w.aimAngle) * w.aimPower * 150); ctx.stroke();
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;

    // power arc around the worm
    const power = w.aimPower;
    const baseA = -Math.PI * 0.82;
    ctx.translate(w.x, w.y - 26);
    ctx.strokeStyle = 'rgba(8,10,22,.55)';
    ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(0, 0, 27, baseA, baseA + Math.PI * 1.44); ctx.stroke();
    ctx.strokeStyle = power > 0.85 ? '#ff4d6d' : power > 0.55 ? '#ff9f1c' : '#7ee081';
    ctx.lineWidth = 3.2;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.arc(0, 0, 27, baseA, baseA + Math.PI * 1.44 * power); ctx.stroke();
    ctx.restore();

    // power text near worm
    const wp = g.worldToScreen(w.x, w.y - 66);
    const ctx2 = this.ctx;
    ctx2.save();
    ctx2.font = '900 9px "Arial Black", sans-serif';
    ctx2.textAlign = 'center';
    ctx2.fillStyle = 'rgba(8,10,22,.65)';
    ctx2.fillRect(wp.x - 20, wp.y - 8, 40, 13);
    ctx2.fillStyle = '#ffe66d';
    ctx2.fillText(`${Math.round(power * 100)}%`, wp.x, wp.y + 2);
    ctx2.restore();
  }

  drawBuildMode(ctx) {
    const g = this.game;
    const w = g.activeWorm;
    if (!w) return;
    ctx.save();
    // grid in build range
    const range = 252;
    ctx.beginPath(); ctx.arc(w.x, w.y - 22, range, 0, TAU); ctx.clip();
    const gx0 = Math.floor((w.x - range) / GRID) * GRID;
    const gx1 = w.x + range;
    const gy0 = Math.floor((w.y - 22 - range) / GRID) * GRID;
    const gy1 = w.y - 22 + range;
    ctx.lineWidth = 1;
    for (let x = gx0; x <= gx1; x += GRID) {
      for (let y = gy0; y <= gy1; y += GRID) {
        const shade = ((x / GRID + y / GRID) & 1) ? 0.045 : 0.02;
        ctx.fillStyle = `rgba(90,200,255,${shade})`;
        ctx.fillRect(x, y, GRID, GRID);
        ctx.strokeStyle = 'rgba(110,215,255,.15)';
        ctx.strokeRect(x + 0.5, y + 0.5, GRID - 1, GRID - 1);
      }
    }
    ctx.restore();

    // range ring
    ctx.save();
    ctx.translate(w.x, w.y - 22);
    ctx.strokeStyle = 'rgba(90,205,255,.35)';
    ctx.lineWidth = 1.2;
    ctx.setLineDash([5, 9]);
    ctx.lineDashOffset = -g.time * 16;
    ctx.beginPath(); ctx.arc(0, 0, range, 0, TAU); ctx.stroke();
    ctx.restore();

    // ghost piece
    const gh = g.buildGhost;
    if (gh) {
      const mat = MATERIALS[gh.material];
      const piece = g.makePiece(gh.type, gh.gx, gh.gy, 0, gh.material, gh.dir);
      ctx.save();
      ctx.globalAlpha = gh.valid ? 0.48 : 0.4;
      piece.drawShape(ctx, mat);
      ctx.globalAlpha = gh.valid ? 0.24 : 0.28;
      ctx.fillStyle = gh.valid ? '#38bdf8' : '#ff4d6d';
      ctx.fillRect(gh.gx * GRID, gh.gy * GRID, GRID, GRID);
      ctx.globalAlpha = 0.9;
      ctx.strokeStyle = gh.valid ? '#7ddcff' : '#ff6b84';
      ctx.lineWidth = 2;
      ctx.setLineDash([6, 4]);
      ctx.strokeRect(gh.gx * GRID + 1, gh.gy * GRID + 1, GRID - 2, GRID - 2);
      ctx.setLineDash([]);
      if (gh.valid) {
        // corner brackets
        const x = gh.gx * GRID, y = gh.gy * GRID;
        ctx.lineWidth = 2.5;
        for (const [cx, cy, dx, dy] of [[x, y, 1, 1], [x + GRID, y, -1, 1], [x, y + GRID, 1, -1], [x + GRID, y + GRID, -1, -1]]) {
          ctx.beginPath(); ctx.moveTo(cx + dx * 12, cy); ctx.lineTo(cx, cy); ctx.lineTo(cx, cy + dy * 12); ctx.stroke();
        }
      }
      ctx.restore();
    }
  }

  drawBuildStatus(ctx) {
    const g = this.game;
    if (g.state !== 'aim' || g.mode !== 'build' || !g.buildGhost || g.activeTeam !== 0) return;
    const gh = g.buildGhost;
    const pos = g.worldToScreen(gh.gx * GRID + GRID / 2, gh.gy * GRID - 8);
    const ctx2 = this.ctx;
    const label = gh.valid
      ? `${MATERIALS[gh.material].label} ${gh.type.toUpperCase()} · ${gh.cost} MATS`
      : gh.reason || 'INVALID';
    ctx2.save();
    ctx2.font = '900 9px "Arial Black", sans-serif';
    const tw = ctx2.measureText(label).width;
    ctx2.fillStyle = 'rgba(5,9,22,.78)';
    ctx2.fillRect(pos.x - tw / 2 - 7, pos.y - 20, tw + 14, 15);
    ctx2.strokeStyle = gh.valid ? 'rgba(56,189,248,.6)' : 'rgba(255,77,109,.7)';
    ctx2.lineWidth = 1;
    ctx2.strokeRect(pos.x - tw / 2 - 7, pos.y - 20, tw + 14, 15);
    ctx2.fillStyle = gh.valid ? '#bdefff' : '#ff8da0';
    ctx2.textAlign = 'center';
    ctx2.fillText(label, pos.x, pos.y - 10);
    ctx2.restore();
  }

  /* ------------------------------------------------------- screen effects */
  drawScreenEffects() {
    const g = this.game;
    const ctx = this.ctx;
    const v = g.view;
    if (g.fx.flash > 0.01) {
      ctx.fillStyle = `rgba(${g.fx.flashColor || '255,180,90'},${Math.min(0.5, g.fx.flash)})`;
      ctx.fillRect(0, 0, v.w, v.h);
    }
    // storm tint
    const storm = clamp((WATER_START - g.waterLevel) / 150, 0, 1);
    if (storm > 0.02) {
      const grad = ctx.createLinearGradient(0, 0, 0, v.h);
      grad.addColorStop(0, `rgba(92,42,160,${storm * 0.2})`);
      grad.addColorStop(0.6, 'rgba(92,42,160,0)');
      grad.addColorStop(1, `rgba(28,8,50,${storm * 0.25})`);
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, v.w, v.h);
    }
    if (g.state === 'over' && g.winner === 0) this.drawConfetti();
    if (g.state === 'over' && g.winner === 1) {
      ctx.fillStyle = 'rgba(80,10,35,.12)';
      ctx.fillRect(0, 0, v.w, v.h);
    }
  }

  drawConfetti() {
    const g = this.game;
    const ctx = this.ctx;
    const v = g.view;
    const t = g.time;
    const colors = ['#ff9f1c', '#ffe66d', '#38bdf8', '#b06bff', '#7ee081', '#ff6b35'];
    for (let i = 0; i < 70; i++) {
      const x = (hash2(i, 11, 3) * v.w + Math.sin(t * 2 + i) * 24) % v.w;
      const speed = 70 + hash2(i, 12, 4) * 90;
      const y = ((hash2(i, 13, 6) * v.h + t * speed) % (v.h + 40)) - 20;
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(t * (1 + i % 4) + i);
      ctx.fillStyle = colors[i % colors.length];
      ctx.globalAlpha = 0.75;
      ctx.fillRect(-2.5, -1, 5, 2.5);
      ctx.restore();
    }
    ctx.globalAlpha = 1;
  }
}

