/* --------------------------------------------------------------- RESULT */
.result-screen {
  z-index: 50;
  background:
    radial-gradient(ellipse at 50% 42%, rgba(255,159,28,.12), transparent 55%),
    rgba(4, 7, 17, .82);
  backdrop-filter: blur(9px);
}
.result-card {
  width: min(660px, 92vw);
  text-align: center;
  padding: clamp(26px, 4vw, 44px);
  background: linear-gradient(150deg, rgba(25, 34, 68, .97), rgba(8, 13, 30, .98));
  border: 1px solid rgba(255, 159, 28, .28);
  border-radius: 5px;
  clip-path: polygon(0 0, calc(100% - 30px) 0, 100% 30px, 100% 100%, 30px 100%, 0 calc(100% - 30px));
  box-shadow: 0 35px 100px rgba(0,0,0,.65), inset 0 1px rgba(255,255,255,.1);
  animation: intro-up .5s cubic-bezier(.2,.8,.2,1) both;
}
.result-screen.victory .result-card { border-color: rgba(255,230,109,.45); }
.result-screen.defeat .result-card { border-color: rgba(255,77,109,.4); }
.result-kicker {
  font: 800 9px/1 var(--display); letter-spacing: .32em; color: rgba(255,255,255,.5);
}
.result-title {
  margin: 10px 0 2px;
  font: 900 clamp(36px, 8vw, 76px)/.9 var(--display);
  font-style: italic; letter-spacing: -.02em;
  color: var(--yellow);
  background: linear-gradient(180deg, #fff9cf 5%, var(--yellow) 35%, var(--orange) 78%, #ff5c2b 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 4px 0 rgba(70,28,6,.7));
}
.result-screen.defeat .result-title {
  background: linear-gradient(180deg, #ffd9e1 5%, #ff6b84 40%, #b5163a 100%);
  -webkit-background-clip: text; background-clip: text;
}
.result-sub {
  margin: 12px auto 24px;
  font: 500 13px/1.5 var(--body); color: rgba(255,255,255,.62); max-width: 390px;
}
.result-stats {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px;
  margin: 0 auto 26px; max-width: 520px;
  border-top: 1px solid rgba(255,255,255,.1);
  border-bottom: 1px solid rgba(255,255,255,.1);
  padding: 16px 0;
}
.result-stats div { display: flex; flex-direction: column; gap: 4px; }
.result-stats b {
  font: 900 clamp(17px, 2.6vw, 24px)/1 var(--display); color: #fff;
}
.result-stats span {
  font: 700 6.5px/1.2 var(--body); letter-spacing: .09em; color: rgba(255,255,255,.38);
}
.result-actions { display: flex; justify-content: center; gap: 10px; }
.result-actions .start-btn { height: 52px; min-width: 210px; }
.result-actions .how-btn { height: 52px; }
.result-foot {
  margin-top: 22px;
  font: 700 7px/1 var(--body); letter-spacing: .2em; color: rgba(255,255,255,.24);
}

/* ------------------------------------------------------------ RESPONSIVE */
@media (max-width: 520px) {
  .mat-chips { display: none !important; }
}
@media (max-width: 780px), (pointer: coarse) {
  .result-stats { grid-template-columns: repeat(3, 1fr); row-gap: 14px; }
  .result-actions { flex-direction: column; align-items: center; }
  .result-actions .how-btn { width: min(210px, 100%); }
}

