import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox','--disable-dev-shm-usage','--use-gl=swiftshader','--enable-unsafe-swiftshader'] });

for (const [name,w,h] of [['mobile',390,844],['landscape',844,390]]) {
  const ctx = await browser.newContext({ viewport:{width:w,height:h}, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type()==='error') errors.push('CONSOLE ' + m.text()); });
  page.on('response', r => { if(r.status()>=400) errors.push('HTTP ' + r.status() + ' ' + r.url()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  await page.getByRole('button', { name: 'Start Game' }).click();
  await page.waitForTimeout(900);

  const boxes = await page.evaluate(() => {
    const ids = ['controls','weaponBar','buildBar','modeBtn','endBtn','activeName','profilePortrait'];
    const out = {};
    for (const id of ids) {
      const el = document.getElementById(id);
      if (!el) continue;
      const r = el.getBoundingClientRect();
      out[id] = {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),right:Math.round(r.right),bottom:Math.round(r.bottom),hidden:el.hidden};
    }
    out.viewport = {w:innerWidth,h:innerHeight};
    out.view = window.__buildBlast.game.view;
    out.controlsCSS = getComputedStyle(document.documentElement).getPropertyValue('--controls-h');
    const cards = [...document.querySelectorAll('#weaponBar .weapon-card')].map(c=>{const r=c.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),bottom:Math.round(r.bottom)}});
    out.weaponCards = cards;
    return out;
  });
  console.log(name, 'LAYOUT', JSON.stringify(boxes));

  // enter build mode
  await page.locator('#modeBtn').click();
  await page.waitForTimeout(400);
  const buildBoxes = await page.evaluate(() => {
    const out = {};
    for (const id of ['buildBar','modeBtn','endBtn']) {
      const el = document.getElementById(id);
      const r = el.getBoundingClientRect();
      out[id] = {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),bottom:Math.round(r.bottom),scrollW:el.scrollWidth,clientW:el.clientWidth};
    }
    out.cards = [...document.querySelectorAll('#buildBar .weapon-card')].map(c=>{const r=c.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),right:Math.round(r.right)}});
    out.chips = [...document.querySelectorAll('#buildBar .mat-chip')].map(c=>{const r=c.getBoundingClientRect();return {x:Math.round(r.x),y:Math.round(r.y),w:Math.round(r.width),h:Math.round(r.height),right:Math.round(r.right)}});
    out.overflowX = document.documentElement.scrollWidth > innerWidth;
    return out;
  });
  console.log(name, 'BUILD', JSON.stringify(buildBoxes));
  await page.screenshot({ path:`/home/runner/work/PlayGround/PlayGround/screenshots/build-${name}.png` });

  // tap near active worm to place a build
  const before = await page.evaluate(() => {
    const g = window.__buildBlast.game;
    const s = g.worldToScreen(g.activeWorm.x + g.activeWorm.facing*70, g.activeWorm.y - 40);
    return {s, mats: [...g.mats], pieces: g.pieces.length, active: g.activeWorm.name};
  });
  await page.touchscreen.tap(before.s.x, before.s.y);
  await page.waitForTimeout(500);
  const afterBuild = await page.evaluate(() => {
    const g = window.__buildBlast.game;
    return {mats: [...g.mats], pieces: g.pieces.length, state:g.state, mode:g.mode};
  });
  console.log(name, 'BUILD TAP', JSON.stringify({before, afterBuild}));
  await page.screenshot({ path:`/home/runner/work/PlayGround/PlayGround/screenshots/built-${name}.png` });

  // cycle material
  await page.locator('#matCycle').click();
  const mat = await page.evaluate(() => window.__buildBlast.game.material);
  console.log(name, 'MATERIAL', mat);

  // back to blast and fire via drag
  await page.locator('#modeBtn').click();
  await page.waitForTimeout(200);
  const fireInfo = await page.evaluate(() => {
    const g = window.__buildBlast.game;
    const w = g.activeWorm;
    const from = g.worldToScreen(w.x, w.y - 31);
    const to = g.worldToScreen(w.x + (w.facing>0?1:-1)*200, w.y - 31 - 150);
    return {from, to};
  });
  await page.mouse.move(fireInfo.from.x, fireInfo.from.y);
  await page.mouse.down();
  await page.mouse.move(fireInfo.to.x, fireInfo.to.y, {steps: 8});
  await page.mouse.up();
  await page.waitForTimeout(500);
  const afterFire = await page.evaluate(() => window.__buildBlast.state);
  console.log(name, 'FIRE', JSON.stringify({fireInfo, afterFire}));
  await page.waitForTimeout(2500);
  await page.screenshot({ path:`/home/runner/work/PlayGround/PlayGround/screenshots/fired-${name}.png` });
  console.log(name, 'AFTER FIRE STATE', JSON.stringify(await page.evaluate(()=>window.__buildBlast.state)));
  console.log(name, 'ERRORS', JSON.stringify(errors));
  await ctx.close();
}
await browser.close();

