const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
page.on('response', r => { if (r.status() >= 400) errors.push('HTTP ' + r.status() + ' ' + r.url()); });

const state = () => page.evaluate(() => window.__buildBlast.state);
const waitFor = async (fn, timeout = 20000, label = '') => {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    if (await page.evaluate(fn)) return true;
    await page.waitForTimeout(150);
  }
  throw new Error('timeout waiting for ' + label);
};

await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.getByRole('button', { name: 'Start Game' }).click();
await page.waitForTimeout(300);
const t0 = await page.evaluate(() => window.__buildBlast.game.timeLeft);
await page.waitForTimeout(2200);
const t1 = await page.evaluate(() => window.__buildBlast.game.timeLeft);
console.log('TIMER', { t0, t1, dropped: t1 < t0 });

// Build two pieces near the player using the debug helper.
const build = await page.evaluate(() => {
  const g = window.__buildBlast.game;
  const w = g.activeWorm;
  const gx = Math.floor((w.x - w.facing * 96) / 48);
  const gy = Math.floor((w.y - 6) / 48);
  const before = [...g.mats];
  const a = window.__buildBlast.place(gx, gy, 'wall', 'wood');
  const b = window.__buildBlast.place(gx, gy - 1, 'wall', 'wood');
  return { a, b, before, after: [...g.mats], pieces: g.pieces.length };
});
console.log('BUILD', build);

// Fire away from the build and wait for the AI to finish.
await page.evaluate(() => {
  const g = window.__buildBlast.game;
  g.activeWorm.aimAngle = -1.05;
  g.activeWorm.aimPower = 0.95;
  window.__buildBlast.fire();
});
await page.waitForTimeout(400);
const afterFire = await state();
await waitFor(() => window.__buildBlast.game.state === 'aim' && window.__buildBlast.game.activeTeam === 0, 20000, 'player turn after AI');
const round2 = await state();
console.log('TURN FLOW', { afterFire, round2 });

// Pass twice to reach round 3 and trigger the storm surge.
for (let i = 0; i < 2; i++) {
  await page.evaluate(() => window.__buildBlast.endTurn());
  await waitFor(() => window.__buildBlast.game.state === 'aim' && window.__buildBlast.game.activeTeam === 0, 20000, 'player turn ' + (i + 2));
