await page.waitForTimeout(1400);
const result = await page.evaluate(() => ({
  visible: !document.getElementById('resultScreen').classList.contains('hidden'),
  title: document.getElementById('resultTitle').textContent,
  stats: document.getElementById('resultStats').innerText
}));
console.log('RESULT', result);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/result-desktop.png' });

// Rematch.
await page.getByRole('button', { name: 'Play Again' }).click();
await page.waitForTimeout(500);
