import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox','--disable-dev-shm-usage','--use-gl=swiftshader','--enable-unsafe-swiftshader'] });
const shots = '/home/runner/work/PlayGround/PlayGround/screenshots';

async function run(name, w, h, dpr = 1) {
  const ctx = await browser.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: dpr, isMobile: w < 1000, hasTouch: w < 1000 });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  page.on('response', r => { if (r.status() >= 400) errors.push('HTTP ' + r.status() + ' ' + r.url()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await page.screenshot({ path: `${shots}/final-start-${name}.png` });
  await page.getByRole('button', { name: 'Start Game' }).click();
  await page.waitForTimeout(800);
  await page.screenshot({ path: `${shots}/final-game-${name}.png` });
  const layout = await page.evaluate(() => ({
    overflowX: document.documentElement.scrollWidth > innerWidth,
    view: window.__buildBlast.game.view,
    hud: document.querySelector('.hud').getBoundingClientRect().toJSON(),
    controls: document.getElementById('controls').getBoundingClientRect().toJSON(),
    banner: document.getElementById('banner').getBoundingClientRect().toJSON()
  }));
  // build mode
  await page.locator('#modeBtn').click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${shots}/final-build-${name}.png` });
  // result
  await page.evaluate(() => {
    const g = window.__buildBlast.game;
    g.worms.filter(w => w.team === 1).forEach(w => { w.hp = 0; w.alive = false; });
    g.checkWin();
  });
  await page.waitForTimeout(1300);
  await page.screenshot({ path: `${shots}/final-result-${name}.png` });
  const result = await page.evaluate(() => {
    const r = document.querySelector('.result-card').getBoundingClientRect();
    return { visible: !document.getElementById('resultScreen').classList.contains('hidden'), card: { x: r.x, y: r.y, w: r.width, h: r.height, bottom: r.bottom }, vh: innerHeight };
  });
  console.log(name, JSON.stringify({ layout, result, errors }));
  await ctx.close();
}

await run('mobile', 390, 844, 2);
await run('landscape', 844, 390, 2);
await run('tablet', 820, 1180, 1);
await run('desktop', 1440, 900, 1);
await run('small', 320, 700, 2);
await browser.close();

